52	SwiftSubflowSrc::update_rtt(simtime_picosec delay) {
53	    // calculate TCP-like RTO.  Not clear this is right for Swift
54	    if (delay!=0){
55	        if (_rtt>0){
56	            uint64_t abs;
57	            if (delay > _rtt)
58	                abs = delay - _rtt;
59	            else
60	                abs = _rtt - delay;
61	
62	            _mdev = 3 * _mdev / 4 + abs/4;
63	            _rtt = 7*_rtt/8 + delay/8;
64	            _rto = _rtt + 4*_mdev;
65	        } else {
66	            _rtt = delay;
67	            _mdev = delay/2;
68	            _rto = _rtt + 4*_mdev;
69	        }
70	    }
71	
72	    if (_rto <_min_rto)
73	        _rto = _min_rto;
74	}
