151	void
152	SwiftSubflowSrc::applySwiftLimits() {
153	    // we call this whenever we've changed cwnd to enforce bounds, just before we actually use the cwnd
154	    if (_swift_cwnd < _src._min_cwnd) {
155	        cout << "hit min cwnd, was" << _swift_cwnd << " now " << _src._min_cwnd << endl;
156	        _swift_cwnd = _src._min_cwnd;
157	    } else if (_swift_cwnd > _src._max_cwnd) {
158	        cout << "hit max cwnd " << _swift_cwnd << " > " << _src._max_cwnd << endl;
159	        _swift_cwnd = _src._max_cwnd;
160	    }
161	    if (_swift_cwnd < _prev_cwnd) {
162	        _last_decrease = eventlist().now();
163	    }
164	    if (_swift_cwnd < mss()) {
165	        _pacing_delay = (_rtt * mss())/_swift_cwnd;
166	        //cout << "swift_cwnd " << ((double)_sub->_swift_cwnd)/_mss << " pacing " << timeAsUs(_pacing_delay) << "us" << endl; 
167	    } else {
168	        _pacing_delay = 0;
169	    }
170	}
