172	void
173	SwiftSubflowSrc::handle_ack(SwiftAck::seq_t ackno, bool packet_was_trimmed) {
174	    simtime_picosec now = eventlist().now();
175	    if (ackno > _last_acked) { // a brand new ack
176	        _RFC2988_RTO_timeout = now + _rto;// RFC 2988 5.3
177	    
178	        if (ackno >= _highest_sent) {
179	            
180	            _highest_sent = ackno;
181	            //cout << timeAsUs(now) << " " << nodename() << " highest_sent now  " << _highest_sent << endl;
182	            _RFC2988_RTO_timeout = timeInf;// RFC 2988 5.2
183	        }
184	
185	        if (!_in_fast_recovery) {
186	            // best behaviour: proper ack of a new packet, when we were expecting it.
187	            // clear timers.  swift has already calculated new cwnd.
188	            _last_acked = ackno;
189	            _dupacks = 0;
190	            _src.log(this, SwiftLogger::SWIFT_RCV);
191	            applySwiftLimits();
192	            send_packets();
193	            return;
194	        }
195	        // We're in fast recovery, i.e. one packet has been
196	        // dropped but we're pretending it's not serious
197	        if (ackno >= _recoverq) { 
198	            // got ACKs for all the "recovery window": resume
199	            // normal service
200	
201	            //uint32_t flightsize = _highest_sent - ackno;
202	            //_cwnd = min(_ssthresh, flightsize + _mss);
203	            // in NewReno, we'd reset the cwnd here, but I think in swift we continue with the delay-adjusted cwnd.
204	
205	            _inflate = 0;
206	            _last_acked = ackno;
207	            _dupacks = 0;
208	            _in_fast_recovery = false;
209	
210	            _src.log(this, SwiftLogger::SWIFT_RCV_FR_END);
211	            _retransmit_cnt = 0;
212	            if (_can_decrease) {
213	                _swift_cwnd = (1 - _src._max_mdf) * _swift_cwnd;
214	                _last_decrease = now;
215	            }
216	            applySwiftLimits();
217	            send_packets();
218	            return;
219	        }
220	        // In fast recovery, and still getting ACKs for the
221	        // "recovery window"
222	        // This is dangerous. It means that several packets
223	        // got lost, not just the one that triggered FR.
224	        uint32_t new_data = ackno - _last_acked;
225	        if (new_data < _inflate) {
226	            _inflate -= new_data;
227	        } else {
228	            _inflate = 0;
229	        }
230	        _last_acked = ackno;
231	        _inflate += mss();
232	        _src.log(this, SwiftLogger::SWIFT_RCV_FR);
233	        retransmit_packet();
234	        applySwiftLimits();
235	        send_packets();
236	        return;
237	    }
238	    // It's a dup ack
239	    if (_in_fast_recovery) { // still in fast recovery; hopefully the prodigal ACK is on it's way
240	        _inflate += mss();
241	        if (_inflate > _swift_cwnd) {
242	            // this is probably bad
243	            _inflate = _swift_cwnd;
244	            cout << "hit inflate limit" << endl;
245	        }
246	        _src.log(this, SwiftLogger::SWIFT_RCV_DUP_FR);
247	        send_packets();
248	        return;
249	    }
250	    // Not yet in fast recovery. What should we do instead?
251	    _dupacks++;
252	
253	    // If the packet was trimmed, bypass the 3-dup-ACK wait and jump straight
254	    // into fast recovery immediately.  The _in_fast_recovery flag will then
255	    // absorb all subsequent trimmed ACKs from the same burst, preventing a
256	    // retransmission storm.
257	    if (_dupacks != 3 && !packet_was_trimmed) { // not yet serious worry
258	        _src.log(this, SwiftLogger::SWIFT_RCV_DUP);
259	        applySwiftLimits();
260	        send_packets();
261	        return;
262	    }
263	    // _dupacks==3
264	    if (_last_acked < _recoverq) {  
265	        /* See RFC 3782: if we haven't recovered from timeouts
266	           etc. don't do fast recovery */
267	        _src.log(this, SwiftLogger::SWIFT_RCV_3DUPNOFR);
268	        return;
269	    }
270	  
271	    // begin fast recovery
272	  
273	    //only count drops in CA state
274	    _drops++;
275	    applySwiftLimits();
276	    retransmit_packet();
277	    _in_fast_recovery = true;
278	    _recoverq = _highest_sent; // _recoverq is the value of the
279	    // first ACK that tells us things
280	    // are back on track
281	    _src.log(this, SwiftLogger::SWIFT_RCV_DUP_FASTXMIT);
282	}
