284	// Note: the data sequence number is the number of Byte1 of the packet, not the last byte.
285	int 
286	SwiftSubflowSrc::send_packets() {
287	    uint32_t c = _swift_cwnd + _inflate;
288	    int sent_count = 0;
289	    //cout << eventlist().now() << " " << nodename() << " cwnd " << _swift_cwnd << " + " << _inflate << endl;
290	    if (!_established){
291	        //send SYN packet and wait for SYN/ACK
292	        Packet * p  = SwiftPacket::new_syn_pkt(_flow, *(_route), 0, 1);
293	        _highest_sent = 0;
294	
295	        p->sendOn();
296	
297	        if(_RFC2988_RTO_timeout == timeInf) {// RFC2988 5.1
298	            _RFC2988_RTO_timeout = eventlist().now() + _rto;
299	        }        
300	        //cout << "Sending SYN, waiting for SYN/ACK" << endl;
301	        return sent_count;
302	    }
303	
304	    if (c < mss()) {
305	        // cwnd is too small to send one packet per RTT, so we will be in pacing mode
306	        assert(_established);
307	        //cout << eventlist().now() << " " << nodename() << " sub-packet cwnd!" << endl;
308	
309	        // Enter pacing mode if we're not already there. If we are in
310	        // pacing mode, we don't reschedule - _pacing_delay will only
311	        // be applied for the next packet.  This is intended to mirror
312	        // what happens with the carosel, where a sent time is
313	        // calculated and then stuck to.  It might make more sense to
314	        // reschedule, as we've more recent information, but seems
315	        // like this isn't what Google does with hardware pacing.
316	        
317	        if (!_pacer.is_pending()) {
318	            _pacer.schedule_send(_pacing_delay);
319	            //cout << eventlist().now() << " " << nodename() << " pacer set for " << timeAsUs(_pacing_delay) << "us" << endl;
320	
321	            // xxx this won't work with app_limited senders.  Fix this
322	            // if we want to simulate app limiting with pacing.
323	            assert(_src._app_limited == -1);
324	        }
325	        return sent_count;
326	    }
327	    
328	    if (_src._app_limited >= 0 && _rtt > 0) {
329	        uint64_t d = (uint64_t)_src._app_limited * _rtt/1000000000;
330	        if (c > d) {
331	            c = d;
332	        }
333	
334	        if (c==0){
335	            //      _RFC2988_RTO_timeout = timeInf;
336	        }
337	    }
338	
339	    while ((_last_acked + c >= _highest_sent + mss()) && _src.more_data_available()) {
340	
341	        if (_pacer.is_pending()) {
342	            //Our cwnd is now greater than one packet and we've passed
343	            //the tests to send in window mode, but we were in pacing
344	            //mode.  Cancel the pacing and return to window mode.
345	            _pacer.cancel();
346	        }
347	        bool sent = send_next_packet();
348	        if (sent) {
349	            sent_count++;
350	        } else {
351	            break;
352	        }
353	
354	        if(_RFC2988_RTO_timeout == timeInf) {// RFC2988 5.1
355	            _RFC2988_RTO_timeout = eventlist().now() + _rto;
356	            //cout << timeAsUs(eventlist().now()) << " " << nodename() << " RTO at " << timeAsUs(_RFC2988_RTO_timeout) << "us" << endl;
357	        }
358	    }
359	    return sent_count;
360	}
361	
362	bool
363	SwiftSubflowSrc::send_next_packet() {
364	    // ask the scheduler if we can send now
365	    if (_src.queuesize(_flow.flow_id()) > 2) {
366	        // no, we can't send.  We'll be called back when we can.
367	        _deferred_send = true;
368	        return false;
369	    }
370	    _deferred_send = false;
371	    
372	    // keep track of DSN associated with SeqNo, so we can retransmit
373	    SwiftPacket::seq_t dsn;
374	    if (_src.more_data_available()) {
375	        dsn = _src.get_next_dsn();
376	    } else {
377	        // cout << timeAsUs(eventlist().now()) << " " << nodename() << " no more data" << endl;
378	        return false;
379	    }
380	
381	    _dsn_map[_highest_sent+1] = dsn;
382	    
383	    SwiftPacket* p = SwiftPacket::newpkt(_flow, *_route, _highest_sent+1, dsn, mss());
384	    //cout << timeAsUs(eventlist().now()) << " " << nodename() << " sent " << _highest_sent+1 << "-" << _highest_sent+mss() << " dsn " << dsn << endl;
385	    _highest_sent += mss();  
386	    _packets_sent += mss();
387	
388	    p->flow().logTraffic(*p, _src, TrafficLogger::PKT_CREATESEND);
389	    p->set_ts(eventlist().now());
390	    p->sendOn();
391	    _pacer.just_sent();
392	    return true;
393	}
