395	void
396	SwiftSubflowSrc::send_callback() {
397	    if (_deferred_send == false) {
398	        // no need to be here
399	        return;
400	    }
401	
402	    _deferred_send = false;
403	    // We had previously wanted to send but queue said no.  Now it says yes.
404	    send_packets();
405	}
