407	void 
408	SwiftSubflowSrc::retransmit_packet() {
409	    cout << timeAsUs(eventlist().now()) << " " << nodename() << " retransmit_packet " << endl;
410	    if (!_established){
411	        assert(_highest_sent == 1);
412	
413	        Packet* p  = SwiftPacket::new_syn_pkt(_flow, *_route, 1, 1);
414	        p->sendOn();
415	
416	        cout << "Resending SYN, waiting for SYN/ACK" << endl;
417	        return;        
418	    }
419	    SwiftPacket::seq_t dsn = _dsn_map[_last_acked+1];
420	    //cout << timeAsUs(eventlist().now()) << " sending seqno " << _last_acked+1 << endl;
421	    SwiftPacket* p = SwiftPacket::newpkt(_flow, *_route, _last_acked+1, dsn, mss());
422	
423	    p->flow().logTraffic(*p, _src, TrafficLogger::PKT_CREATESEND);
424	    p->set_ts(eventlist().now());
425	    p->sendOn();
426	
427	    _packets_sent += mss();
428	
429	    if(_RFC2988_RTO_timeout == timeInf) {// RFC2988 5.1
430	        _RFC2988_RTO_timeout = eventlist().now() + _rto;
431	    }
432	}
433	
434	void
435	SwiftSubflowSrc::receivePacket(Packet& pkt) 
436	{
437	    simtime_picosec ts_echo;
438	    SwiftAck *p = (SwiftAck*)(&pkt);
439	    SwiftAck::seq_t ackno = p->ackno();
440	    SwiftAck::seq_t ds_ackno = p->ds_ackno();
441	    bool packet_was_trimmed = p->is_trimmed();
442	    pkt.flow().logTraffic(pkt,*this,TrafficLogger::PKT_RCVDESTROY);
443	  
444	    ts_echo = p->ts_echo();
445	    p->free();
446	
447	    if (ackno < _last_acked) {
448	        return;
449	    }
450	
451	    if (ackno==0){
452	        _established = true;
453	    } else if (ackno>0 && !_established) {
454	        cout << "Should be _established " << ackno << endl;
455	        assert(false);
456	    }
457	
458	    assert(ackno >= _last_acked);  // no dups or reordering allowed in this simple simulator
459	
460	    if (packet_was_trimmed) {
461	        // Bypass delay math: the header arrived fast via the high-priority trim
462	        // queue, so ts_echo reflects near-zero queuing — feeding it into
463	        // adjust_cwnd() would make Swift think the network is empty and increase
464	        // CWND.  Apply max-MDF penalty here instead.
465	        simtime_picosec now = eventlist().now();
466	        _can_decrease = (now - _last_decrease) >= _rtt;
467	        if (_can_decrease) {
468	            _swift_cwnd = _swift_cwnd * (1.0 - max_mdf());
469	            _last_decrease = now;
470	        }
471	        applySwiftLimits();
472	        _src.log(this, SwiftLogger::SWIFT_RCV_DUP_FASTXMIT);
473	    } else {
474	        // Standard path: full packet arrived, use its timestamp for delay measurement.
475	        simtime_picosec delay = eventlist().now() - ts_echo;
476	        adjust_cwnd(delay, ackno);
477	    }
478	
479	    _src.update_dsn_ack(ds_ackno);
480	
481	    // Pass the trimmed flag into handle_ack so it can bypass the 3-dup-ACK
482	    // wait and enter fast recovery immediately, while still using the state
483	    // machine to prevent a retransmission storm on subsequent trimmed ACKs.
484	    handle_ack(ackno, packet_was_trimmed);
485	}
