487	void
488	SwiftSubflowSrc::rtx_timer_hook(simtime_picosec now, simtime_picosec period) {
489	    //cout << timeAsUs(eventlist().now()) << " " << nodename() << " rtx_timer_hook" << endl;
490	    if (now <= _RFC2988_RTO_timeout || _RFC2988_RTO_timeout==timeInf) 
491	        return;
492	
493	    if (_highest_sent == 0) 
494	        return;
495	
496	    cout << timeAsUs(eventlist().now()) << " " << nodename() << " At " << now/(double)1000000000<< " RTO " << _rto/1000000000 << " MDEV " 
497	         << _mdev/1000000000 << " RTT "<< _rtt/1000000000 << " SEQ " << _last_acked / mss() << " HSENT "  << _highest_sent 
498	         << " CWND "<< _swift_cwnd/mss() << " FAST RECOVERY? " <<         _in_fast_recovery << " Flow ID " 
499	         << str()  << endl;
500	
501	    // here we can run into phase effects because the timer is checked
502	    // only periodically for ALL flows but if we keep the difference
503	    // between scanning time and real timeout time when restarting the
504	    // flows we should minimize them !
505	    if(!_rtx_timeout_pending) {
506	        _rtx_timeout_pending = true;
507	
508	        // check the timer difference between the event and the real value
509	        simtime_picosec too_late = now - (_RFC2988_RTO_timeout);
510	 
511	        // careful: we might calculate a negative value if _rto suddenly drops very much
512	        // to prevent overflow but keep randomness we just divide until we are within the limit
513	        while(too_late > period) too_late >>= 1;
514	
515	        // carry over the difference for restarting
516	        simtime_picosec rtx_off = (period - too_late)/200;
517	 
518	        eventlist().sourceIsPendingRel(*this, rtx_off);
519	
520	        //reset our rtx timerRFC 2988 5.5 & 5.6
521	
522	        _rto *= 2;
523	        //if (_rto > timeFromMs(1000))
524	        //  _rto = timeFromMs(1000);
525	        _RFC2988_RTO_timeout = now + _rto;
526	    }
527	}
528	
529	void SwiftSubflowSrc::doNextEvent() {
530	    if(_rtx_timeout_pending) {
531	        _rtx_timeout_pending = false;
532	
533	        _src.log(this, SwiftLogger::SWIFT_TIMEOUT);
534	
535	        /*
536	          if (_in_fast_recovery) {
537	          uint32_t flightsize = _highest_sent - _last_acked;
538	          _cwnd = min(_ssthresh, flightsize + _mss);
539	          }
540	
541	          deflate_window();
542	
543	          _cwnd = _mss;
544	        */
545	        _in_fast_recovery = false;
546	        _recoverq = _highest_sent;
547	
548	        if (_established)
549	            _highest_sent = _last_acked + mss();
550	
551	        _dupacks = 0;
552	        _retransmit_cnt++;
553	        if (_retransmit_cnt >= _src._rtx_reset_threshold) {
554	            _swift_cwnd = _src._min_cwnd;
555	        } else if (eventlist().now() - _last_decrease >= _rtt) {
556	            _swift_cwnd *= (1.0 -_src._max_mdf);
557	        }
558	        // Enforce bounds, update _last_decrease, and recalculate pacing delay
559	        // (Algorithm 1, lines 26-32: clamp + t_last_decrease + pacing must apply after all three cases)
560	        applySwiftLimits();
561	        retransmit_packet();
562	    }
563	}
