566	SwiftSubflowSrc::connect(SwiftSink& sink, const Route& routeout, const Route& routeback, uint32_t flow_id, BaseScheduler* scheduler) {
567	    _subflow_sink = sink.connect(_src, *this, routeback);
568	    Route* new_route = routeout.clone(); // make a copy, as we may be switching routes and don't want to append the sink more than once
569	    new_route->push_back(_subflow_sink);
570	    _route = new_route;
571	    _flow.set_id(get_id()); // identify the packet flow with the source that generated it
572	    cout << "connect, flow id is now " << _flow.get_id() << endl;
573	    assert(scheduler);
574	    scheduler->add_src(_flow.flow_id(), this);
