578	SwiftSubflowSrc::move_path() {
579	    cout << timeAsUs(eventlist().now()) << " " << nodename() << " td move_path\n";
580	    if (_src._paths.size() == 0) {
581	        cout << nodename() << " cant move_path\n";
582	        return;
583	    }
584	    // Wrap path index rather than asserting -- PLB on long flows can exhaust
585	    // a linear list; cycling back gives fresh entropy instead of crashing.
