613	SwiftSrc::SwiftSrc(SwiftRtxTimerScanner& rtx_scanner, SwiftLogger* logger, TrafficLogger* pktlogger, 
614	                   EventList &eventlst)
615	    : EventSource(eventlst,"swift"),  _logger(logger), _traffic_logger(pktlogger), _rtx_timer_scanner(&rtx_scanner)
616	{
617	    _mss = Packet::data_packet_size();
618	    _scheduler = NULL;
619	    _maxcwnd = 0xffffffff;//200*_mss;
620	    _flow_size = ((uint64_t)1)<<63;
621	    _stop_time = 0;
622	    _stopped = false;
623	    _app_limited = -1;
624	    _highest_dsn_sent = 0;
625	    _start_time = 0;
626	    _flow_finished = false;
627	    _end_trigger = 0;
628	
629	    // swift cc init
630	    _ai = 1.0;  // increase constant.  Value is a guess
631	    _beta = 0.8;   // decrease constant.  Value is a guess
632	    _max_mdf = 0.5; // max multiplicate decrease factor.  Value is a guess                                                      
633	    _base_delay = timeFromUs((uint32_t)20);    // configured base target delay.  To be confirmed by experiment - reproduce fig 17
634	    _h = _base_delay/6.55;            // path length scaling constant.  Value is a guess, will be clarified by experiment
635	    _rtx_reset_threshold = 5; // value is a guess
636	    _min_cwnd = 10;  // guess - if we go less than 10 bytes, we probably get into rounding 
637	    _max_cwnd = 1000 * _mss;  // maximum cwnd we can use.  Guess - how high should we allow cwnd to go?  Presumably something like B*target_delay?
638	
639	    // PLB init
640	    _plb = false; // enable using enable_plb()
641	
642	    // flow scaling
643	    _fs_range = 5 * _base_delay;
644	    _fs_min_cwnd = 0.1;  // note: in packets                                                                                                                         
645	    _fs_max_cwnd = 100;   // note: in packets
646	    _fs_alpha = _fs_range / ((1.0 / sqrt(_fs_min_cwnd)) -  (1.0 / sqrt(_fs_max_cwnd)));
647	    //double a = 1.0 / sqrt(_fs_min_cwnd);
648	    //double b = 1.0 / sqrt(_fs_max_cwnd);
649	    //cout << "a " << a << " b " << b << " range " << _fs_range << endl;
650	    //cout << _fs_range / ((1.0 / sqrt(_fs_min_cwnd)) -  (1.0 / sqrt(_fs_max_cwnd))) << endl;
651	                
652	    //cout << "_fs_alpha: " << _fs_alpha << endl;
653	    _fs_beta = - _fs_alpha / sqrt(_fs_max_cwnd);
654	}
