818	    double fs_delay = _fs_alpha/sqrt(cwnd/_mss) + _fs_beta;  // _sub->_swift_cwnd is in bytes
819	    //cout << "fs_delay " << fs_delay << " range " << _fs_range << " _sub->_swift_cwnd/_mss " << _sub->_swift_cwnd/_mss << " sqrt " << sqrt(_sub->_swift_cwnd/_mss) << " beta " << _fs_beta << endl;
820	    //cout << "fs_alpha " << _fs_alpha << endl;
821	    
822	    if (fs_delay > _fs_range) {
823	        fs_delay = _fs_range;
824	    }
825	    if (fs_delay < 0.0) {
826	        fs_delay = 0.0;
827	    }
828	
829	    if (cwnd == 0) {
830	        fs_delay = 0.0;
831	    }
832	
833	    simtime_picosec hop_delay = route.hop_count() * _h;
834	    return _base_delay + fs_delay + hop_delay;
