881	SwiftPacer::schedule_send(simtime_picosec delay) {
882	    _interpacket_delay = delay;
883	    _next_send = _last_send + _interpacket_delay;
884	    if (_next_send <= eventlist().now()) {
885	        // Tricky!  We're going in to pacing mode, but it's more than
886	        // the pacing delay since we last sent.  Presumably the best
887	        // thing is to immediately send, and then pacing will kick in
888	        // next time round.
889	        _next_send = eventlist().now();
890	        doNextEvent();
891	        return;
892	    }
893	    eventlist().sourceIsPending(*this, _next_send);
894	}
