950	// Note: _cumulative_ack is the last byte we've ACKed.
951	// seqno is the first byte of the new packet.
952	void
953	SwiftSubflowSink::receivePacket(Packet& pkt) {
954	    SwiftPacket *p = (SwiftPacket*)(&pkt);
955	    SwiftPacket::seq_t seqno = p->seqno();
956	    simtime_picosec ts = p->ts();
957	    //cout << "receivePacket seq" << seqno << endl;
958	    int size = p->size(); // TODO: the following code assumes all packets are the same size
959	    pkt.flow().logTraffic(pkt,*this,TrafficLogger::PKT_RCVDESTROY);
960	
961	    // Handle trimmed (header-only) packets: payload was stripped at a switch.
962	    // Send a flagged ACK immediately so the sender can apply instant MD and
963	    // retransmit without waiting for 3 dup-ACKs or RTO.
964	    if (pkt.header_only()) {
965	        _drops++;
966	        p->free();
967	        send_ack(ts, true);  // trimmed=true: tells sender to apply MD immediately
968	        return;
969	    }
970	
971	    _packets+= p->size();
972	
973	    if (seqno == _cumulative_ack+1) { // it's the next expected seq no
974	        _cumulative_ack = seqno + size - 1;
975	        // are there any additional received packets we can now ack?
976	        while (!_received.empty() && (_received.front() == _cumulative_ack+1) ) {
977	            _received.pop_front();
978	            _cumulative_ack += size;
979	        }
980	    } else if (seqno < _cumulative_ack+1) {
981	        // it is before the next expected sequence - must be a spurious retransmit.
982	        // We want to see if this happens - it generally shouldn't
983	        cout << "Spurious retransmit received!\n";
984	    } else {
985	        // it's not the next expected sequence number
986	        if (_received.empty()) {
987	            _received.push_front(seqno);
988	            //it's a drop - in this simulator there are no reorderings.
989	            // [Note: if we ever add multipath, fix this!]
990	            _drops += (size + seqno-_cumulative_ack-1)/size;
991	        } else if (seqno > _received.back()) {
992	            // likely case - new packet above a hole
993	            _received.push_back(seqno);
994	        } else {
995	            // uncommon case - it fills a hole, but not first hole
996	            list<uint64_t>::iterator i;
997	            for (i = _received.begin(); i != _received.end(); i++) {
998	                if (seqno == *i) break; // it's a bad retransmit
999	                if (seqno < (*i)) {
1000	                    _received.insert(i, seqno);
1001	                    break;
1002	                }
1003	            }
1004	        }
1005	    }
1006	
1007	    _sink.receivePacket(pkt);
1008	    p->free();
1009	
1010	    // whatever the cumulative ack does (eg filling holes), the echoed TS is always from
1011	    // the packet we just received
1012	    send_ack(ts, false);
1013	}
