12	// ===========================================================================
13	//                        Static parameter defaults
14	// ===========================================================================
15	//
16	// These match the FASTFLOW paper Sec 3.5 reference settings. main_fastflow
17	// recomputes _bdp_bytes, _base_rtt, _target_rtt, _fi_const, _md_const from
18	// the actual topology before flows start, so these defaults only matter for
19	// unit tests that don't initialise the topology first.
20	
21	uint16_t FastflowSrc::_mtu          = 4000;
22	double   FastflowSrc::_fd_const     = 0.8;
23	double   FastflowSrc::_fi_const     = 0.25;
24	double   FastflowSrc::_md_const     = 2.0;
25	double   FastflowSrc::_qa_scaling   = 0.8;
26	double   FastflowSrc::_wtd_alpha    = 0.125;
27	double   FastflowSrc::_wtd_thresh   = 0.25;
28	uint32_t FastflowSrc::_k_fastinc    = 2;
29	simtime_picosec FastflowSrc::_base_rtt   = timeFromUs((uint32_t)12);
30	simtime_picosec FastflowSrc::_target_rtt = timeFromUs((uint32_t)18);
31	uint32_t FastflowSrc::_bdp_bytes    = 1500000;
32	bool     FastflowSrc::_enable_ra_qa   = false;
33	bool     FastflowSrc::_enable_credits = false;
34	bool     FastflowSrc::_enable_mcc     = false;
35	bool     FastflowSrc::_trim_supported = true;
