37	// ===========================================================================
38	//                        FastflowSrc — constructor
39	// ===========================================================================
40	FastflowSrc::FastflowSrc(FastflowRtxTimerScanner& rtx_scanner,
41	                         TrafficLogger* pktlogger, EventList& eventlist)
42	    : EventSource(eventlist, "fastflow_src"),
43	      _flow(pktlogger),
44	      _pacer(*this, eventlist),
45	      _traffic_logger(pktlogger)
46	{
47	    _established   = false;
48	    _route         = NULL;
49	    _sink          = NULL;
50	    _path_index    = 0;
51	
52	    _highest_sent  = 0;
53	    _last_acked    = 0;
54	    _flow_size     = ((uint64_t)1) << 62;
55	    _packets_sent  = 0;
56	
57	    // Initial cwnd: 1 BDP (paper Sec 3.5 — max cwnd is 1.25 BDP)
58	    _cwnd          = std::max((uint32_t)_mtu, _bdp_bytes);
59	    _acked         = 0;
60	    _bytes_ignored = 0;
61	    _bytes_to_ignore = 0;
62	    _trigger_qa    = false;
63	    _avg_wtd       = 0.0;
64	    _fast_inc_count = 0;
65	    _in_fast_inc   = false;
66	    _qa_end        = 0;
67	    _last_decrease = 0;
68	
69	    _rtt           = 0;
70	    _rto           = timeFromMs(1);
71	    _mdev          = 0;
72	    _min_rto       = timeFromUs((uint32_t)100);
73	    _RFC2988_RTO_timeout = 0;
74	    _rtx_timeout_pending = false;
75	    _retransmit_cnt = 0;
76	    _drops         = 0;
77	
78	    _initial_burst_remaining = _enable_credits ? _bdp_bytes : ((uint64_t)1 << 62);
79	    _receiver_credits = 0;
80	    _msg_start_time = 0;
81	    _msg_acked      = 0;
82	    _msg_target_bw  = 0.0;
83	    _msg_tolerance  = 0.85;
84	    _trimmed_bytes  = 0;
85	
86	    _start_time     = 0;
87	    _flow_finished  = false;
88	    _end_trigger    = NULL;
89	
90	    _pacing_delay   = 0;
91	    _rtx_scanner    = &rtx_scanner;
92	    _rtx_scanner->registerSrc(*this);
93	
94	    _flow.set_id(get_id());
95	    _nodename = "fastflow_src" + std::to_string(get_id());
