98	// ===========================================================================
99	//                        Connection setup
100	// ===========================================================================
101	void
102	FastflowSrc::connect(const Route& routeout, const Route& routeback,
103	                     FastflowSink& sink, simtime_picosec starttime) {
104	    _sink  = &sink;
105	    Route* new_route = routeout.clone();
106	    new_route->push_back(&sink);
107	    _route = new_route;
108	    sink.connect(*this, routeback);
109	
110	    _start_time = starttime;
111	    if (starttime != TRIGGER_START) {
112	        eventlist().sourceIsPending(*this, starttime);
113	    }
114	}
115	
116	void
117	FastflowSrc::set_paths(vector<const Route*>* rt_list) {
118	    _paths.clear();
119	    for (size_t i = 0; i < rt_list->size(); i++) {
120	        _paths.push_back(rt_list->at(i));
121	    }
122	}
