129	// ===========================================================================
130	//                        Trigger interface
131	// ===========================================================================
132	void
133	FastflowSrc::activate() {
134	    _start_time = eventlist().now();
135	    startflow();
136	}
137	
138	void
139	FastflowSrc::set_end_trigger(Trigger& trigger) {
140	    _end_trigger = &trigger;
141	}
142	
143	void
144	FastflowSrc::doNextEvent() {
145	    if (_rtx_timeout_pending) {
146	        // Treat the timeout exactly like a packet trim: arm QuickAdapt,
147	        // bump retransmit_cnt, retransmit the next-expected byte.
148	        _rtx_timeout_pending = false;
149	        _trigger_qa = true;
150	
151	        if (_cwnd > _mtu) _cwnd -= _mtu;
152	        clamp_cwnd();
153	
154	        _retransmit_cnt++;
155	        if (can_retransmit(_last_acked + 1)) {
156	            retransmit_seqno(_last_acked + 1);
157	        }
158	        send_packets();   // try to push more after recovery
159	        return;
160	    }
161	    startflow();
162	}
163	
164	void
165	FastflowSrc::startflow() {
166	    if (_established) return;
167	    _established = true;
168	    if (_start_time == 0 || _start_time == TRIGGER_START) {
169	        _start_time = eventlist().now();
170	    }
171	    _msg_start_time = eventlist().now();
172	    _msg_acked = 0;
173	    send_packets();
174	}
175	
176	// ===========================================================================
177	//                        Main control loop (Algorithm 1)
178	// ===========================================================================
179	//
180	// Order matches the paper exactly:
181	//   1) bookkeeping (acked, bytes_ignored)
182	//   2) if trim/timeout -> handle_trim
183	//   3) else (normal ACK):
184	//        bypass while in post-QA ignore window
185	//        compute can_decrease (WTD)
186	//        try QuickAdapt, then FastIncrease (either may short-circuit)
187	//        4-case logic on (ECN, RTT vs trtt)
188	//   4) clamp cwnd into [MTU, 1.25 BDP]
189	
190	void
191	FastflowSrc::handle_ack(FastflowAck& ack) {
192	    simtime_picosec now = eventlist().now();
193	
194	    // Bytes the ACK represents
195	    uint64_t new_bytes = (ack.ackno() > _last_acked)
196	                             ? (ack.ackno() - _last_acked)
197	                             : 0;
198	    _acked         += new_bytes;
199	    _bytes_ignored += new_bytes;
200	    _msg_acked     += new_bytes;
201	    if (ack.ackno() > _last_acked) {
202	        _last_acked = ack.ackno();
203	        _RFC2988_RTO_timeout = now + _rto;
204	        if (_last_acked >= _highest_sent) {
205	            _RFC2988_RTO_timeout = 0;
206	        }
207	    }
208	
209	    // Trim / timeout path (paper Algo 1 lines 28-34)
210	    if (ack.is_trimmed()) {
211	        handle_trim(ack);
212	        clamp_cwnd();
213	        send_packets();
214	        maybe_report_completion();
215	        return;
216	    }
217	
218	    // Post-QuickAdapt ignore window: we already applied the new cwnd, so
219	    // ignore the in-flight stale congestion signals until they drain.
220	    if (_bytes_ignored < _bytes_to_ignore) {
221	        send_packets();
222	        maybe_report_completion();
223	        return;
224	    }
225	
226	    // RTT sample (timestamp echo)
227	    simtime_picosec rtt_sample = now - ack.ts_echo();
228	    update_rtt(rtt_sample);
229	
230	    bool ecn = ack.ecn_echo();
231	    bool can_dec = wait_to_decrease(ecn, now);
232	
233	    // QuickAdapt fires *only* if a trim/timeout previously armed it.
234	    // fast_increase fires only when we've had >cwnd subsequent clean bytes.
235	    bool adp = quick_adapt(ack, now);
236	    bool finc = fast_increase(ack);
237	    if (adp || finc) {
238	        clamp_cwnd();
239	        send_packets();
240	        maybe_report_completion();
241	        return;
242	    }
243	
244	    // Four-case logic
245	    simtime_picosec trtt = _target_rtt;
246	    bool healthy = _enable_mcc && message_is_healthy(now);
247	    uint16_t sz = (new_bytes > 0) ? (uint16_t)std::min((uint64_t)_mtu, new_bytes) : _mtu;
248	
249	    if (ecn && rtt_sample <= trtt && can_dec) {
250	        if (!healthy) fair_decrease(sz);
251	    }
252	    else if (ecn && rtt_sample > trtt && can_dec) {
253	        if (!healthy) {
254	            multiplicative_decrease(sz, rtt_sample);
255	            fair_decrease(sz);  // paper: MD additionally applies FD
256	        }
257	    }
258	    else if (!ecn && rtt_sample > trtt) {
259	        if (healthy) {
260	            // MCC override: treat as a clean RTT and grow.
261	            multiplicative_increase(sz, rtt_sample);
262	        } else {
263	            fair_increase(sz);
264	        }
265	    }
266	    else { // !ecn && rtt <= trtt
267	        multiplicative_increase(sz, rtt_sample);
268	        fair_increase(sz);  // paper: MI additionally applies FI
269	    }
270	
271	    clamp_cwnd();
272	    send_packets();
273	    maybe_report_completion();
274	}
275	
276	// ---------- Sub-procedures --------------------------------------------------
277	
278	bool
279	FastflowSrc::wait_to_decrease(bool ecn, simtime_picosec now) {
280	    // EMA of ECN markings (paper Sec 3.5.1)
281	    _avg_wtd = _wtd_alpha * (ecn ? 1.0 : 0.0) + (1.0 - _wtd_alpha) * _avg_wtd;
282	    if (_avg_wtd < _wtd_thresh) return false;
283	    // Also enforce once-per-RTT
284	    if (_rtt > 0 && (now - _last_decrease) < _rtt) return false;
285	    return true;
286	}
287	
288	bool
289	FastflowSrc::quick_adapt(FastflowAck& ack, simtime_picosec now) {
290	    // Algorithm 2 — at most once per target RTT.
291	    bool adapted = false;
292	    if (now < _qa_end && _qa_end != 0) {
293	        // still inside the previous QA window; just accumulate.
294	        return false;
295	    }
296	    if (_trigger_qa && _qa_end != 0) {
297	        _trigger_qa = false;
298	        adapted = true;
299	
300	        // Idea 3 (RA-QA): use receiver-stamped bytes if available.
301	        uint64_t basis = _acked;
302	        if (_enable_ra_qa && ack.recv_bytes_trtt() > 0) {
303	            basis = ack.recv_bytes_trtt();
304	        }
305	        uint64_t new_cwnd = (uint64_t)((double)std::max(basis, (uint64_t)_mtu) * _qa_scaling);
306	        _cwnd = (uint32_t)std::max(new_cwnd, (uint64_t)_mtu);
307	
308	        // grace window — ignore stale congestion signals from in-flight pkts
309	        uint64_t unacked = (_highest_sent > _last_acked)
310	                              ? (_highest_sent - _last_acked) : 0;
311	        _bytes_to_ignore = unacked;
312	        _bytes_ignored   = 0;
313	        _last_decrease   = now;
314	    }
315	    // open the next QA window regardless
316	    _qa_end = now + _target_rtt;
317	    _acked = 0;
318	    return adapted;
319	}
320	
321	bool
322	FastflowSrc::fast_increase(FastflowAck& ack) {
323	    // Algorithm 3
324	    bool clean = !ack.ecn_echo();
325	    simtime_picosec rtt = _rtt;
326	    bool rtt_near_base = (rtt == 0) ||
327	                         (rtt <= _base_rtt + (_target_rtt - _base_rtt) / 4);
328	
329	    if (clean && rtt_near_base) {
330	        uint64_t new_bytes = (ack.ackno() > _last_acked)
331	                                  ? (ack.ackno() - _last_acked) : _mtu;
332	        _fast_inc_count += new_bytes;
333	        if (_fast_inc_count > _cwnd || _in_fast_inc) {
334	            _cwnd += _k_fastinc * _mtu;
335	            _in_fast_inc = true;
336	            return true;
337	        }
338	    } else {
339	        _fast_inc_count = 0;
340	        _in_fast_inc = false;
341	    }
342	    return false;
343	}
344	
345	// Eq. 1
346	void
347	FastflowSrc::fair_decrease(uint16_t pkt_size) {
348	    double d = ((double)_cwnd / (double)_bdp_bytes) * _fd_const * (double)pkt_size;
349	    if ((uint32_t)d >= _cwnd) {
350	        _cwnd = _mtu;
351	    } else {
352	        _cwnd -= (uint32_t)d;
353	    }
354	    _last_decrease = eventlist().now();
355	}
356	
357	// Eq. 2
358	void
359	FastflowSrc::multiplicative_decrease(uint16_t pkt_size, simtime_picosec rtt_sample) {
360	    double ratio = (double)(rtt_sample - _target_rtt) / (double)rtt_sample;
361	    double dec = ratio * _md_const * (double)pkt_size;
362	    if (dec > (double)pkt_size) dec = (double)pkt_size;
363	    if ((uint32_t)dec >= _cwnd) {
364	        _cwnd = _mtu;
365	    } else {
366	        _cwnd -= (uint32_t)dec;
367	    }
368	    _last_decrease = eventlist().now();
369	}
370	
371	// Eq. 3
372	void
373	FastflowSrc::fair_increase(uint16_t pkt_size) {
374	    double inc = ((double)pkt_size / (double)_cwnd) * (double)_mtu * _fi_const;
375	    _cwnd += (uint32_t)inc;
376	}
377	
378	// Eq. 4
379	void
380	FastflowSrc::multiplicative_increase(uint16_t pkt_size, simtime_picosec rtt_sample) {
381	    // mi = brtt / (trtt - brtt), bounded
382	    if (_target_rtt <= _base_rtt) return;
383	    double mi = (double)_base_rtt / (double)(_target_rtt - _base_rtt);
384	    double inc = ((double)(_target_rtt - rtt_sample) / (double)rtt_sample)
385	                 * (double)pkt_size / (double)_cwnd
386	                 * (double)_mtu * mi;
387	    if (inc > (double)pkt_size) inc = (double)pkt_size;
388	    if (inc < 0) inc = 0;
389	    _cwnd += (uint32_t)inc;
390	}
391	
392	void
393	FastflowSrc::clamp_cwnd() {
394	    uint32_t hi = (uint32_t)(_bdp_bytes * 1.25);
395	    if (_cwnd > hi) _cwnd = hi;
396	    if (_cwnd < _mtu) _cwnd = _mtu;
397	}
398	
399	void
400	FastflowSrc::update_rtt(simtime_picosec sample) {
401	    if (sample == 0) return;
402	    if (_rtt == 0) {
403	        _rtt  = sample;
404	        _mdev = sample / 2;
405	        _rto  = _rtt + 4 * _mdev;
406	    } else {
407	        simtime_picosec diff = (sample > _rtt) ? (sample - _rtt) : (_rtt - sample);
408	        _mdev = (3 * _mdev) / 4 + diff / 4;
409	        _rtt  = (7 * _rtt) / 8 + sample / 8;
410	        _rto  = _rtt + 4 * _mdev;
411	    }
412	    if (_rto < _min_rto) _rto = _min_rto;
413	}
414	
415	void
416	FastflowSrc::handle_trim(FastflowAck& ack) {
417	    // Algo 1 lines 28-34, augmented with: (a) a per-seqno dedup so a single
418	    // dropped packet doesn't get retransmitted twice for the same trim
419	    // burst, and (b) cwnd-gated retransmissions via _rtx_queue so the
420	    // recovery traffic itself doesn't storm the bottleneck buffer.
421	    if (_cwnd > _mtu) _cwnd -= _mtu;
422	    _trigger_qa = true;
423	    _drops++;
424	    simtime_picosec now = eventlist().now();
425	
426	    FastflowPacket::seq_t sq = ack.trim_seqno();
427	    if (sq == 0) sq = _last_acked + 1;
428	    if (sq > _last_acked) {
429	        // Account this packet as no-longer-in-flight so subsequent cwnd
430	        // budgeting reflects on-the-wire bytes accurately.
431	        _trimmed_bytes += _mtu;
432	        enqueue_retransmit(sq);
433	    }
434	    if (_bytes_ignored >= _bytes_to_ignore) {
435	        quick_adapt(ack, now);
436	    }
437	}
438	
439	bool
440	FastflowSrc::can_retransmit(FastflowPacket::seq_t seqno) const {
441	    auto it = _rtx_blockuntil.find(seqno);
442	    if (it == _rtx_blockuntil.end()) return true;
443	    simtime_picosec now = eventlist().now();
444	    return now >= it->second;
445	}
446	
447	void
448	FastflowSrc::enqueue_retransmit(FastflowPacket::seq_t seqno) {
449	    if (seqno <= _last_acked) return;
450	    if (!can_retransmit(seqno)) return;
451	    if (_rtx_pending.count(seqno)) return;
452	    _rtx_queue.push_back(seqno);
453	    _rtx_pending.insert(seqno);
454	}
455	
456	void
457	FastflowSrc::retransmit_seqno(FastflowPacket::seq_t seqno) {
458	    if (seqno <= _last_acked) return;
459	    if (seqno > _flow_size) return;
460	    uint32_t sz = std::min((uint32_t)_mtu,
461	                           (uint32_t)(_flow_size + 1 - seqno));
462	    FastflowPacket* p = FastflowPacket::newpkt(_flow, *_route, seqno, sz);
463	    p->set_ts(eventlist().now());
464	    p->flow().logTraffic(*p, *this, TrafficLogger::PKT_CREATESEND);
465	    p->sendOn();
466	    _packets_sent += 1;
467	    simtime_picosec block = (_rtt > 0) ? _rtt : timeFromUs((uint32_t)1000);
468	    _rtx_blockuntil[seqno] = eventlist().now() + block;
469	    if (_RFC2988_RTO_timeout == 0) {
470	        _RFC2988_RTO_timeout = eventlist().now() + _rto;
471	    }
472	}
473	
474	// ===========================================================================
475	//                        MCC: message health
476	// ===========================================================================
477	bool
478	FastflowSrc::message_is_healthy(simtime_picosec now) const {
479	    if (_msg_target_bw <= 0.0) return true;
480	    if (_msg_start_time == 0)  return true;
481	    double elapsed_sec = timeAsSec(now - _msg_start_time);
482	    double expected = elapsed_sec * _msg_target_bw;
483	    double thresh   = expected * _msg_tolerance;
484	    return (double)_msg_acked >= thresh;
485	}
486	
487	// ===========================================================================
488	//                        Sending side
489	// ===========================================================================
490	bool
491	FastflowSrc::can_send_one_mtu() const {
492	    uint64_t inflight = (_highest_sent > _last_acked)
493	                         ? (_highest_sent - _last_acked) : 0;
494	    if (inflight + _mtu > _cwnd) return false;
495	
496	    if (_enable_credits) {
497	        if (_initial_burst_remaining >= _mtu) return true;
498	        return (_receiver_credits >= _mtu);
499	    }
500	    return true;
501	}
502	
503	int
504	FastflowSrc::send_packets() {
505	    if (!_established) return 0;
506	    int count = 0;
507	    while (_highest_sent + _mtu <= _flow_size + _mtu) {
508	        if (!can_send_one_mtu()) break;
509	        if (!send_next_packet()) break;
510	        count++;
511	    }
512	    if (_highest_sent < _flow_size && _RFC2988_RTO_timeout == 0) {
513	        _RFC2988_RTO_timeout = eventlist().now() + _rto;
514	    }
515	    return count;
516	}
517	
518	bool
519	FastflowSrc::send_next_packet() {
520	    if (_highest_sent >= _flow_size) return false;
521	    uint32_t sz = std::min((uint32_t)_mtu,
522	                           (uint32_t)(_flow_size - _highest_sent));
523	
524	    FastflowPacket* p = FastflowPacket::newpkt(_flow, *_route,
525	                                               _highest_sent + 1, sz);
526	    p->set_ts(eventlist().now());
527	    p->flow().logTraffic(*p, *this, TrafficLogger::PKT_CREATESEND);
528	    _highest_sent += sz;
529	    _packets_sent += 1;
530	
531	    if (_enable_credits) {
532	        if (_initial_burst_remaining >= sz) {
533	            _initial_burst_remaining -= sz;
534	        } else if (_receiver_credits >= sz) {
535	            _receiver_credits -= sz;
536	        }
537	    }
538	
539	    p->sendOn();
540	    return true;
541	}
542	
543	void
544	FastflowSrc::retransmit_packet() {
545	    // Legacy entry point — defer to the dedup-aware path so callers don't
546	    // accidentally storm the queue.
547	    if (_last_acked >= _flow_size) return;
548	    if (can_retransmit(_last_acked + 1)) {
549	        retransmit_seqno(_last_acked + 1);
550	    }
551	}
552	
553	// ===========================================================================
554	//                        Packet receive (ACK / pull)
555	// ===========================================================================
556	void
557	FastflowSrc::receivePacket(Packet& pkt) {
558	    pkt.flow().logTraffic(pkt, *this, TrafficLogger::PKT_RCVDESTROY);
559	
560	    // Detect packet type by attempted downcast.
561	    FastflowPull* pull = dynamic_cast<FastflowPull*>(&pkt);
562	    if (pull) {
563	        _receiver_credits += pull->credit_bytes();
564	        pull->free();
565	        send_packets();
566	        return;
567	    }
568	    FastflowAck* ack = dynamic_cast<FastflowAck*>(&pkt);
569	    if (!ack) {
570	        pkt.free();
571	        return;
572	    }
573	    handle_ack(*ack);
574	    ack->free();
575	}
