580	void
581	FastflowSrc::rtx_timer_hook(simtime_picosec now, simtime_picosec period) {
582	    if (!_established) return;
583	    if (_RFC2988_RTO_timeout == 0) return;
584	    if (now < _RFC2988_RTO_timeout) return;
585	    if (_highest_sent == 0) return;
586	    if (_rtx_timeout_pending) return;
587	    _rtx_timeout_pending = true;
588	    _rto *= 2;
589	    if (_rto > timeFromMs(1000)) _rto = timeFromMs(1000);
590	    _RFC2988_RTO_timeout = now + _rto;
591	    eventlist().sourceIsPendingRel(*this, 0);  // fire ASAP
592	}
