597	void
598	FastflowSrc::maybe_report_completion() {
599	    if (_flow_finished) return;
600	    if (_last_acked < _flow_size) return;
601	    _flow_finished = true;
602	    simtime_picosec fct = eventlist().now() - _start_time;
603	    // Same line format as Swift so plot_swift_results.py parses it natively.
604	    cout << "FCT " << _name
605	         << " start_us "  << timeAsUs(_start_time)
606	         << " finish_us " << timeAsUs(eventlist().now())
607	         << " fct_us "    << timeAsUs(fct)
608	         << " size_bytes " << _flow_size
609	         << endl;
610	    if (_end_trigger) _end_trigger->activate();
611	}
