619	      _cumulative_ack(0), _drops(0),
620	      _bytes_received_window(0), _window_start(0),
621	      _credit_mode(false), _host_linkspeed(0),
622	      _next_credit_time(0), _credit_quantum(FastflowSrc::_mtu),
623	      _coflow_id(NO_COFLOW), _sender_id(0),
624	      _bytes_received_total(0)
625	{
626	    _nodename = "fastflow_sink";
627	}
628	
629	void
630	FastflowSink::connect(FastflowSrc& src, const Route& routeback) {
