652	void
653	FastflowSink::update_recv_window(uint32_t pkt_size, simtime_picosec now) {
654	    if (_window_start == 0) _window_start = now;
655	    if (now - _window_start >= FastflowSrc::_target_rtt) {
656	        _bytes_received_window = 0;
657	        _window_start = now;
658	    }
659	    _bytes_received_window += pkt_size;
660	}
661	
662	void
663	FastflowSink::receivePacket(Packet& pkt) {
664	    simtime_picosec now = _src ? _src->eventlist().now() : 0;
665	    FastflowPacket* p = dynamic_cast<FastflowPacket*>(&pkt);
666	    if (!p) {
667	        // Unknown packet type — drop silently.
668	        pkt.free();
669	        return;
670	    }
671	    pkt.flow().logTraffic(pkt, *this, TrafficLogger::PKT_RCVDESTROY);
672	
673	    // Trimmed packet: header arrived, payload was stripped en route.
674	    if (pkt.header_only()) {
675	        _drops++;
676	        send_ack(*p, /*trimmed=*/true, now);
677	        p->free();
678	        return;
679	    }
680	
681	    uint32_t sz = p->size();
682	    update_recv_window(sz, now);
683	    _bytes_received_total += sz;
684	
685	    // Coflow progress update (Idea 2)
686	    if (_coflow_id != NO_COFLOW) {
687	        CoflowRegistry::instance().update_progress(_coflow_id, _sender_id, sz);
688	    }
689	
690	    // Track cumulative ACK
691	    FastflowPacket::seq_t seqno = p->seqno();
692	    if (seqno == _cumulative_ack + 1) {
693	        _cumulative_ack = seqno + sz - 1;
694	        while (!_received.empty() && _received.front() == _cumulative_ack + 1) {
695	            _received.pop_front();
696	            _cumulative_ack += sz;
697	        }
698	    } else if (seqno < _cumulative_ack + 1) {
699	        // duplicate / out of order before cum_ack — ignore
700	    } else {
701	        if (_received.empty() || seqno > _received.back()) {
702	            _received.push_back(seqno);
703	        } else {
704	            for (auto it = _received.begin(); it != _received.end(); ++it) {
705	                if (seqno == *it) break;
706	                if (seqno < *it) { _received.insert(it, seqno); break; }
707	            }
708	        }
709	    }
710	
711	    send_ack(*p, /*trimmed=*/false, now);
712	    p->free();
713	}
714	
715	void
716	FastflowSink::send_ack(FastflowPacket& pkt, bool trimmed, simtime_picosec now) {
717	    bool ecn = (pkt.flags() & ECN_CE) != 0;
718	    // For trim ACKs we report the seqno of the trimmed packet so the source
719	    // can retransmit *that specific* packet rather than blindly resending
720	    // _last_acked + 1 (which storms when several packets are trimmed).
721	    FastflowPacket::seq_t trim_sq = trimmed ? pkt.seqno() : 0;
722	    FastflowAck* ack = FastflowAck::newpkt(pkt.flow(), *_route_back,
723	                                           _cumulative_ack,
724	                                           trim_sq,
725	                                           pkt.ts(),
726	                                           ecn,
727	                                           trimmed,
728	                                           _bytes_received_window);
729	    ack->flow().logTraffic(*ack, *this, TrafficLogger::PKT_CREATESEND);
730	    ack->sendOn();
731	
732	    // Idea 1: if in credit mode, opportunistically piggy-back a credit grant.
733	    issue_credit_if_due(now);
734	}
735	
736	void
737	FastflowSink::issue_credit_if_due(simtime_picosec now) {
738	    if (!_credit_mode) return;
739	    if (now < _next_credit_time) return;
740	    if (!_route_back || !_src) return;
741	
742	    // Default fair quantum: 1 MTU per (RTT / N_active_senders). We
743	    // approximate by issuing 1 MTU per base RTT here — the sender
744	    // accumulates credits and gates send accordingly.
745	    uint32_t fair_q     = FastflowSrc::_mtu;
746	    uint32_t priority_q = (uint32_t)(_credit_quantum * 2);
747	
748	    uint32_t grant = fair_q;
749	    if (_coflow_id != NO_COFLOW &&
750	        CoflowRegistry::instance().policy() == COFLOW_ASYMMETRIC) {
751	        grant = CoflowRegistry::instance().credit_for(_coflow_id, _sender_id,
752	                                                      fair_q, priority_q);
753	    }
754	    if (grant > 0) {
755	        FastflowPull* pull = FastflowPull::newpkt(_src->flow(), *_route_back,
756	                                                  grant);
757	        pull->sendOn();
758	    }
759	    _next_credit_time = now + FastflowSrc::_base_rtt;
760	}
