765	FastflowPacer::FastflowPacer(FastflowSrc& src, EventList& eventlist)
766	    : EventSource(eventlist, "fastflow_pacer"),
767	      _src(&src), _interpacket_delay(0),
768	      _last_send(eventlist.now()), _next_send(0) {}
769	
770	void
771	FastflowPacer::schedule_send(simtime_picosec delay) {
772	    _interpacket_delay = delay;
773	    _next_send = _last_send + delay;
774	    if (_next_send <= eventlist().now()) {
775	        _next_send = eventlist().now();
776	        doNextEvent();
777	        return;
778	    }
779	    eventlist().sourceIsPending(*this, _next_send);
780	}
781	
782	void
783	FastflowPacer::cancel() {
784	    _interpacket_delay = 0;
785	    _next_send = 0;
786	    eventlist().cancelPendingSource(*this);
787	}
788	
789	void
790	FastflowPacer::just_sent() {
791	    _last_send = eventlist().now();
792	}
793	
794	void
795	FastflowPacer::doNextEvent() {
796	    _src->send_next_packet();
797	    _last_send = eventlist().now();
798	    if (_src->_pacing_delay > 0) {
799	        schedule_send(_src->_pacing_delay);
800	    } else {
801	        _interpacket_delay = 0;
802	        _next_send = 0;
803	    }
804	}
