bool
FastflowSrc::can_send_one_mtu() const {
    uint64_t gross = (_highest_sent > _last_acked)
                       ? (_highest_sent - _last_acked) : 0;
    // Trimmed packets are no longer on the wire — subtract them from the
    // in-flight estimate so the cwnd budget tracks actual bytes-in-flight.
    uint64_t inflight = (gross > _trimmed_bytes)
                          ? (gross - _trimmed_bytes) : 0;
    if (inflight + _mtu > _cwnd) return false;

    if (_enable_credits) {
        if (_initial_burst_remaining >= _mtu) return true;
        return (_receiver_credits >= _mtu);
    }
    return true;
}

int
FastflowSrc::send_packets() {
    if (!_established) return 0;
    int count = 0;

    // Phase 1: drain the retransmit queue, gated by cwnd budget. Trim ACKs
    // can arrive in bursts; if every trim immediately retransmitted bypassing
    // cwnd, the recovery traffic itself would storm the bottleneck. By
    // funneling through can_send_one_mtu() we cap retransmit bandwidth at the
    // same window the source uses for new data.
    while (!_rtx_queue.empty() && can_send_one_mtu()) {
        FastflowPacket::seq_t sq = _rtx_queue.front();
        _rtx_queue.pop_front();
        if (sq <= _last_acked) continue;          // already ACKed
        if (!_rtx_pending.count(sq)) continue;    // already retransmitted
        if (!can_retransmit(sq)) {
            // Inside the per-seqno block window — let the RTO timer reissue.
            // Drop from queue (it's still tracked in _rtx_pending so the
