bool
FastflowSrc::enqueue_retransmit(FastflowPacket::seq_t seqno) {
    if (seqno <= _last_acked) return false;
    if (!can_retransmit(seqno)) return false;
    if (_rtx_pending.count(seqno)) return false;
    _rtx_queue.push_back(seqno);
    _rtx_pending.insert(seqno);
    return true;
}

// When _last_acked advances, drop any rtx state for seqnos at or below the
// new cum-ack. We may have queued a retransmit that the receiver then
// acknowledged (e.g. ACK overtook a trim, or RTO retransmit was redundant);
// in that case the trimmed-bytes accounting needs to be released too, or the
// cwnd budget will be permanently overstated.
void
FastflowSrc::prune_acked_rtx_state() {
    auto it = _rtx_pending.begin();
    while (it != _rtx_pending.end()) {
        if (*it <= _last_acked) {
            if (_trimmed_bytes >= _mtu) _trimmed_bytes -= _mtu;
            it = _rtx_pending.erase(it);
        } else {
            ++it;
        }
    }
    auto bit = _rtx_blockuntil.begin();
    while (bit != _rtx_blockuntil.end()) {
        if (bit->first <= _last_acked) {
            bit = _rtx_blockuntil.erase(bit);
        } else {
            ++bit;
        }
    }
}

input.new_string:
// Block-window dedup state grows once per trim; reclaim entries that have
// either passed their no-retransmit deadline or are below the new cum-ack.
void
FastflowSrc::prune_blockuntil() {
    simtime_picosec now = eventlist().now();
    auto it = _rtx_blockuntil.begin();
    while (it != _rtx_blockuntil.end()) {
        if (it->first <= _last_acked || now >= it->second) {
            it = _rtx_blockuntil.erase(it);
        } else {
            ++it;
        }
    }
}

