// Cumulative-ack-style retransmit: always retransmit the contiguous
// hole at _last_acked + 1, not the specific trimmed seqno reported in
// the ACK. This avoids two failure modes:
//   (a) each trim ACK retransmitting a different seqno => storm
//   (b) holes getting "stuck" because retransmits fire for higher
//       seqnos that just go into the sink's OOO buffer
// The per-seqno block window (now keyed on _last_acked+1) still throttles
// back-to-back retransmits of the same hole; if the hole moves, the new
// hole isn't blocked.
FastflowPacket::seq_t hole = _last_acked + 1;
if (hole <= _flow_size && can_retransmit(hole)) {
    retransmit_seqno(hole);
    _retransmits_dbg++;
} else if (hole <= _flow_size) {
    _blocked_rtx_dbg++;
}

