330	bool
331	FastflowSrc::fast_increase(FastflowAck& ack) {
332	    // Algorithm 3
333	    bool clean = !ack.ecn_echo();
334	    simtime_picosec rtt = _rtt;
335	    bool rtt_near_base = (rtt == 0) ||
336	                         (rtt <= _base_rtt + (_target_rtt - _base_rtt) / 4);
337	
338	    if (clean && rtt_near_base) {
339	        uint64_t new_bytes = (ack.ackno() > _last_acked)
340	                                  ? (ack.ackno() - _last_acked) : _mtu;
341	        _fast_inc_count += new_bytes;
342	        if (_fast_inc_count > _cwnd || _in_fast_inc) {
343	            _cwnd += _k_fastinc * _mtu;
344	            _in_fast_inc = true;
345	            return true;
346	        }
347	    } else {
348	        _fast_inc_count = 0;
349	        _in_fast_inc = false;
350	    }
351	    return false;
352	}
