355	void
356	FastflowSrc::fair_decrease(uint16_t pkt_size) {
357	    double d = ((double)_cwnd / (double)_bdp_bytes) * _fd_const * (double)pkt_size;
358	    if ((uint32_t)d >= _cwnd) {
359	        _cwnd = _mtu;
360	    } else {
361	        _cwnd -= (uint32_t)d;
362	    }
363	    _last_decrease = eventlist().now();
364	}
365	
366	// Eq. 2
367	void
368	FastflowSrc::multiplicative_decrease(uint16_t pkt_size, simtime_picosec rtt_sample) {
369	    double ratio = (double)(rtt_sample - _target_rtt) / (double)rtt_sample;
370	    double dec = ratio * _md_const * (double)pkt_size;
371	    if (dec > (double)pkt_size) dec = (double)pkt_size;
372	    if ((uint32_t)dec >= _cwnd) {
373	        _cwnd = _mtu;
374	    } else {
375	        _cwnd -= (uint32_t)dec;
376	    }
377	    _last_decrease = eventlist().now();
378	}
