380	// Eq. 3
381	void
382	FastflowSrc::fair_increase(uint16_t pkt_size) {
383	    double inc = ((double)pkt_size / (double)_cwnd) * (double)_mtu * _fi_const;
384	    _cwnd += (uint32_t)inc;
