388	void
389	FastflowSrc::multiplicative_increase(uint16_t pkt_size, simtime_picosec rtt_sample) {
390	    // mi = brtt / (trtt - brtt), bounded
391	    if (_target_rtt <= _base_rtt) return;
392	    double mi = (double)_base_rtt / (double)(_target_rtt - _base_rtt);
393	    double inc = ((double)(_target_rtt - rtt_sample) / (double)rtt_sample)
394	                 * (double)pkt_size / (double)_cwnd
395	                 * (double)_mtu * mi;
396	    if (inc > (double)pkt_size) inc = (double)pkt_size;
397	    if (inc < 0) inc = 0;
398	    _cwnd += (uint32_t)inc;
