408	void
409	FastflowSrc::update_rtt(simtime_picosec sample) {
410	    if (sample == 0) return;
411	    if (_rtt == 0) {
412	        _rtt  = sample;
413	        _mdev = sample / 2;
414	        _rto  = _rtt + 4 * _mdev;
415	    } else {
416	        simtime_picosec diff = (sample > _rtt) ? (sample - _rtt) : (_rtt - sample);
417	        _mdev = (3 * _mdev) / 4 + diff / 4;
418	        _rtt  = (7 * _rtt) / 8 + sample / 8;
419	        _rto  = _rtt + 4 * _mdev;
420	    }
421	    if (_rto < _min_rto) _rto = _min_rto;
422	}
