424	void
425	FastflowSrc::handle_trim(FastflowAck& ack) {
426	    // Algo 1 lines 28-34, augmented with: (a) a per-seqno dedup so a single
427	    // dropped packet doesn't get retransmitted twice for the same trim
428	    // burst, and (b) cwnd-gated retransmissions via _rtx_queue so the
429	    // recovery traffic itself doesn't storm the bottleneck buffer.
430	    if (_cwnd > _mtu) _cwnd -= _mtu;
431	    _trigger_qa = true;
432	    _drops++;
433	    simtime_picosec now = eventlist().now();
434	
435	    FastflowPacket::seq_t sq = ack.trim_seqno();
436	    if (sq == 0) sq = _last_acked + 1;
437	    if (sq > _last_acked) {
438	        if (can_retransmit(sq)) {
439	            retransmit_seqno(sq);
440	            _retransmits_dbg++;
441	        } else {
442	            _rtx_pending.insert(sq);
443	            _blocked_rtx_dbg++;
444	        }
445	    }
446	    if (_bytes_ignored >= _bytes_to_ignore) {
447	        quick_adapt(ack, now);
448	    }
