452	FastflowSrc::can_retransmit(FastflowPacket::seq_t seqno) const {
453	    auto it = _rtx_blockuntil.find(seqno);
454	    if (it == _rtx_blockuntil.end()) return true;
455	    simtime_picosec now = eventlist().now();
