void
FastflowSink::receivePacket(Packet& pkt) {
    simtime_picosec now = _src ? _src->eventlist().now() : 0;
    FastflowPacket* p = dynamic_cast<FastflowPacket*>(&pkt);
    if (!p) {
        // Unknown packet type — drop silently.
        pkt.free();
        return;
    }
    pkt.flow().logTraffic(pkt, *this, TrafficLogger::PKT_RCVDESTROY);

    // Trimmed packet: header arrived, payload was stripped en route.
    if (pkt.header_only()) {
        _drops++;
        send_ack(*p, /*trimmed=*/true, now);
        p->free();
        return;
    }

    uint32_t sz = p->size();
    update_recv_window(sz, now);
    _bytes_received_total += sz;

    // Coflow progress update (Idea 2)
    if (_coflow_id != NO_COFLOW) {
        CoflowRegistry::instance().update_progress(_coflow_id, _sender_id, sz);
    }

    // Track cumulative ACK
    FastflowPacket::seq_t seqno = p->seqno();
    if (seqno == _cumulative_ack + 1) {
        _cumulative_ack = seqno + sz - 1;
        while (!_received.empty() && _received.front() == _cumulative_ack + 1) {
            _received.pop_front();
            _cumulative_ack += sz;
        }
    } else if (seqno < _cumulative_ack + 1) {
        // duplicate / out of order before cum_ack — ignore
    } else {
        if (_received.empty() || seqno > _received.back()) {
            _received.push_back(seqno);
        } else {
            for (auto it = _received.begin(); it != _received.end(); ++it) {
                if (seqno == *it) break;
                if (seqno < *it) { _received.insert(it, seqno); break; }
            }
        }
    }

    send_ack(*p, /*trimmed=*/false, now);
    p->free();
}

void
FastflowSink::send_ack(FastflowPacket& pkt, bool trimmed, simtime_picosec now) {
    bool ecn = (pkt.flags() & ECN_CE) != 0;
    // For trim ACKs we report the seqno of the trimmed packet so the source
    // can retransmit *that specific* packet rather than blindly resending
    // _last_acked + 1 (which storms when several packets are trimmed).
    FastflowPacket::seq_t trim_sq = trimmed ? pkt.seqno() : 0;
    FastflowAck* ack = FastflowAck::newpkt(pkt.flow(), *_route_back,
                                           _cumulative_ack,
                                           trim_sq,
                                           pkt.ts(),
                                           ecn,
                                           trimmed,
                                           _bytes_received_window);
    ack->flow().logTraffic(*ack, *this, TrafficLogger::PKT_CREATESEND);
    ack->sendOn();

    // Idea 1: if in credit mode, opportunistically piggy-back a credit grant.
    issue_credit_if_due(now);
}

void
FastflowSink::issue_credit_if_due(simtime_picosec now) {
    if (!_credit_mode) return;
    if (now < _next_credit_time) return;
    if (!_route_back || !_src) return;

    // Default fair quantum: 1 MTU per (RTT / N_active_senders). We
    // approximate by issuing 1 MTU per base RTT here — the sender
    // accumulates credits and gates send accordingly.
    uint32_t fair_q     = FastflowSrc::_mtu;
    uint32_t priority_q = (uint32_t)(_credit_quantum * 2);

    uint32_t grant = fair_q;
    if (_coflow_id != NO_COFLOW &&
        CoflowRegistry::instance().policy() == COFLOW_ASYMMETRIC) {
        grant = CoflowRegistry::instance().credit_for(_coflow_id, _sender_id,
                                                      fair_q, priority_q);
    }
    if (grant > 0) {
        FastflowPull* pull = FastflowPull::newpkt(_src->flow(), *_route_back,
                                                  grant);
        pull->sendOn();
    }
    _next_credit_time = now + FastflowSrc::_base_rtt;
}

