163	    // and drain it on the next event whose timestamp clears the block —
164	    // otherwise blocked trims would be silently lost between block-expiry
165	    // and the next RTO fire (which happens at a much coarser cadence).
166	    std::map<FastflowPacket::seq_t, simtime_picosec> _rtx_blockuntil;
