1	// -*- c-basic-offset: 4; indent-tabs-mode: nil -*-
2	//
3	// Entry point for the FASTFLOW simulator.
4	//
5	// Modes (selected by -mode <name>):
6	//   fastflow             : vanilla sender-based FASTFLOW (default).
7	//   fastflow+eqds        : FASTFLOW sender + EQDS-style receiver credits.
8	//   fastflow+eqds+mcc    : above + Message-Level CC overrides.
9	//   fastflow+eqds+mcc+coflow : above + asymmetric coflow credit shaping.
10	//
11	// Independently toggleable:
12	//   -ra_qa on|off        : Receiver-Anchored QuickAdapt (Idea 3).
13	//   -trimming on|off     : enable packet trimming (CompositeQueue, default on).
14	//
15	// CLI parity with main_swift.cpp is kept where possible so plot scripts and
16	// connection-matrix files remain interchangeable across protocols.
17	
18	#include <iostream>
19	#include <list>
20	#include <math.h>
21	#include <sstream>
22	#include <string.h>
23	
24	#include "config.h"
25	#include "eventlist.h"
26	#include "network.h"
27	#include "pipe.h"
28	#include "logfile.h"
29	#include "loggers.h"
30	#include "clock.h"
31	#include "compositequeue.h"
32	#include "topology.h"
33	#include "connection_matrix.h"
34	#include "fat_tree_topology.h"
35	#include "main.h"
36	#include "trigger.h"
37	
38	#include "fastflow/fastflow.h"
39	#include "fastflow/coflow_state.h"
40	
41	#define DEFAULT_NODES   128
42	#define DEFAULT_QUEUE_SIZE 500   // packets
43	
44	EventList eventlist;
45	Logfile* lg;
46	
47	static void exit_error(const char* progname) {
48	    cout << "Usage: " << progname
49	         << " [-tm tm-file] [-topo topo-file] [-nodes N] [-q Q] [-mtu MTU]"
50	         << " [-linkspeed Mbps] [-end us]"
51	         << " [-trimming on|off] [-ra_qa on|off]"
52	         << " [-mode fastflow|fastflow+eqds|fastflow+eqds+mcc|fastflow+eqds+mcc+coflow]"
53	         << " [-msg_target_bw Bps] [-msg_tolerance 0..1]"
54	         << " [-coflow_gap bytes]"
55	         << endl;
56	    exit(1);
57	}
58	
59	static bool flag_on(const char* s) {
60	    return strcmp(s, "on") == 0 || strcmp(s, "true") == 0 || strcmp(s, "1") == 0;
61	}
62	
63	int main(int argc, char** argv) {
64	    Clock c(timeFromSec(5.0 / 100.0), eventlist);
65	
66	    uint32_t no_of_nodes = DEFAULT_NODES;
67	    mem_b queuesize = DEFAULT_QUEUE_SIZE;
68	    linkspeed_bps linkspeed = speedFromMbps((double)HOST_NIC);
69	    uint32_t packet_size = 4000;
70	    simtime_picosec endtime = timeFromMs(1.2);
71	
72	    bool trimming = true;
73	    bool ra_qa = false;
74	    bool use_credits = false;
75	    bool use_mcc = false;
76	    bool use_coflow = false;
77	
78	    double msg_target_bw = 0.0;
79	    double msg_tolerance = 0.85;
80	    uint64_t coflow_gap_bytes = 4ULL * 1024 * 1024;
81	
82	    const char* tm_file   = NULL;
83	    const char* topo_file = NULL;
84	
85	    stringstream logfile_name(ios_base::out);
86	    logfile_name << "logout.dat";
87	
88	    // ----- CLI parsing --------------------------------------------------
89	    int i = 1;
90	    while (i < argc) {
91	        if (!strcmp(argv[i], "-o"))            { logfile_name.str(""); logfile_name << argv[++i]; }
92	        else if (!strcmp(argv[i], "-nodes"))   { no_of_nodes = atoi(argv[++i]); }
93	        else if (!strcmp(argv[i], "-tm"))      { tm_file = argv[++i]; }
94	        else if (!strcmp(argv[i], "-topo"))    { topo_file = argv[++i]; }
95	        else if (!strcmp(argv[i], "-q"))       { queuesize = atoi(argv[++i]); }
96	        else if (!strcmp(argv[i], "-mtu"))     { packet_size = atoi(argv[++i]); }
97	        else if (!strcmp(argv[i], "-linkspeed")) { linkspeed = speedFromMbps(atof(argv[++i])); }
98	        else if (!strcmp(argv[i], "-end"))     { endtime = timeFromUs(atof(argv[++i])); }
99	        else if (!strcmp(argv[i], "-trimming")) { trimming = flag_on(argv[++i]); }
100	        else if (!strcmp(argv[i], "-ra_qa"))   { ra_qa = flag_on(argv[++i]); }
101	        else if (!strcmp(argv[i], "-mode")) {
102	            const char* m = argv[++i];
103	            if (!strcmp(m, "fastflow")) {
104	                use_credits = false; use_mcc = false; use_coflow = false;
105	            } else if (!strcmp(m, "fastflow+eqds")) {
106	                use_credits = true;  use_mcc = false; use_coflow = false;
107	            } else if (!strcmp(m, "fastflow+eqds+mcc")) {
108	                use_credits = true;  use_mcc = true;  use_coflow = false;
109	            } else if (!strcmp(m, "fastflow+eqds+mcc+coflow")) {
110	                use_credits = true;  use_mcc = true;  use_coflow = true;
111	            } else {
112	                cerr << "Unknown mode '" << m << "'\n"; exit_error(argv[0]);
113	            }
114	        }
115	        else if (!strcmp(argv[i], "-msg_target_bw")) { msg_target_bw = atof(argv[++i]); }
116	        else if (!strcmp(argv[i], "-msg_tolerance")) { msg_tolerance = atof(argv[++i]); }
117	        else if (!strcmp(argv[i], "-coflow_gap"))    { coflow_gap_bytes = strtoull(argv[++i], NULL, 10); }
118	        else { exit_error(argv[0]); }
119	        i++;
120	    }
121	
122	    Packet::set_packet_size(packet_size);
123	    eventlist.setEndtime(endtime);
124	    queuesize = queuesize * Packet::data_packet_size();
125	    srand(13);
126	
127	    // ----- Wire FASTFLOW global toggles --------------------------------
128	    FastflowSrc::_mtu = packet_size;
129	    FastflowSrc::_enable_ra_qa = ra_qa;
130	    FastflowSrc::_enable_credits = use_credits;
131	    FastflowSrc::_enable_mcc = use_mcc;
132	    FastflowSrc::_trim_supported = trimming;
133	    if (!trimming) FastflowSrc::_md_const = 4.0;
134	
135	    CoflowRegistry::instance().reset();
136	    if (use_coflow) {
137	        CoflowRegistry::instance().set_policy(COFLOW_ASYMMETRIC);
138	        CoflowRegistry::instance().set_gap_threshold(coflow_gap_bytes);
139	    }
140	
141	    cout << "[fastflow] mode "
142	         << (use_credits ? (use_mcc ? (use_coflow ? "fastflow+eqds+mcc+coflow"
143	                                                  : "fastflow+eqds+mcc")
144	                                    : "fastflow+eqds")
145	                         : "fastflow")
146	         << " trimming=" << trimming
147	         << " ra_qa="    << ra_qa
148	         << " mtu="      << packet_size
149	         << " nodes="    << no_of_nodes
150	         << " linkspeed=" << (linkspeed / 1000000) << " Mbps"
151	         << endl;
152	
153	    Logfile logfile(logfile_name.str(), eventlist);
154	    lg = &logfile;
155	    logfile.setStartTime(timeFromSec(0));
156	
157	    // ----- Topology -----------------------------------------------------
158	    FatTreeTopology* top;
159	    queue_type net_qt    = trimming ? COMPOSITE : RANDOM;
160	    queue_type sender_qt = FAIR_PRIO;
161	    if (topo_file) {
162	        top = FatTreeTopology::load(topo_file, NULL, eventlist, queuesize,
163	                                    net_qt, sender_qt);
164	    } else {
165	        top = new FatTreeTopology(no_of_nodes, linkspeed, queuesize,
166	                                  NULL, &eventlist, NULL, net_qt, sender_qt, 0);
167	    }
168	    no_of_nodes = top->no_of_nodes();
169	    cout << "[fastflow] actual nodes " << no_of_nodes << endl;
170	
171	    // ----- Derive FASTFLOW parameters from the topology -----------------
172	    //
173	    // Per paper Sec 3.5:
174	    //   base_rtt is the empty-network RTT (2 * link_latency * hops + queuing-free
175	    //     switch traversal). At 800Gbps with hop_latency ~600ns and 3 tier
176	    //     traversal, we approximate base_rtt = 12us. For correctness we set
177	    //     it from queuesize/linkspeed-derived BDP.
178	    //   target_rtt = 1.5 * base_rtt
179	    //   fi, mi scaled by gamma = bdp / reference_bdp (100Gbps,12us)
180	    //
181	    // We use 12us as the reference because the FASTFLOW paper uses that.
182	
183	    simtime_picosec brtt = timeFromUs((uint32_t)12);
184	    simtime_picosec trtt = (brtt * 3) / 2;
185	    uint64_t bdp_bytes = (uint64_t)((double)linkspeed * timeAsSec(brtt) / 8.0);
186	    uint64_t reference_bdp = (uint64_t)((double)speedFromMbps(100000.0) * timeAsSec(timeFromUs((uint32_t)12)) / 8.0);
187	    double gamma = (double)bdp_bytes / (double)reference_bdp;
188	
189	    FastflowSrc::_base_rtt   = brtt;
190	    FastflowSrc::_target_rtt = trtt;
191	    FastflowSrc::_bdp_bytes  = (uint32_t)bdp_bytes;
192	    FastflowSrc::_fi_const   = 0.25 * gamma;
193	    // mi is recomputed per-call inside multiplicative_increase but uses
194	    // _base_rtt and _target_rtt which we just set.
195	    FastflowSrc::_fd_const   = 0.8;
196	    FastflowSrc::_md_const   = trimming ? 2.0 : 4.0;
197	    FastflowSrc::_qa_scaling = 0.8;
198	    FastflowSrc::_wtd_alpha  = 0.125;
199	    FastflowSrc::_wtd_thresh = 0.25;
200	    FastflowSrc::_k_fastinc  = 2;
201	
202	    cout << "[fastflow] brtt=" << timeAsUs(brtt) << "us trtt=" << timeAsUs(trtt) << "us"
203	         << " bdp=" << bdp_bytes << "B gamma=" << gamma << endl;
204	
205	    // ----- Connection matrix --------------------------------------------
206	    ConnectionMatrix* conns = new ConnectionMatrix(no_of_nodes);
207	    if (tm_file) {
208	        cout << "[fastflow] loading traffic matrix " << tm_file << endl;
209	        if (!conns->load(tm_file)) exit(-1);
210	    } else {
211	        cout << "[fastflow] reading traffic matrix from stdin" << endl;
212	        conns->load(cin);
213	    }
214	    if (conns->N != no_of_nodes) {
215	        cerr << "[fastflow] tm nodes " << conns->N
216	             << " != topology nodes " << no_of_nodes << endl;
217	        exit(-1);
218	    }
219	
220	    // ----- Flow construction --------------------------------------------
221	    // RTO scan period must be much shorter than typical RTO so a stuck
222	    // hole (e.g. because the trim ACK was truly dropped in the fabric)
223	    // gets recovered within a few RTTs — not after 10ms.
224	    FastflowRtxTimerScanner rtx_scanner(timeFromUs((uint32_t)50), eventlist);
225	
226	    vector<connection*>* all_conns = conns->getAllConnections();
227	    vector<const Route*>*** net_paths = new vector<const Route*>**[no_of_nodes];
228	    for (uint32_t a = 0; a < no_of_nodes; a++) {
229	        net_paths[a] = new vector<const Route*>*[no_of_nodes];
230	        for (uint32_t b = 0; b < no_of_nodes; b++) net_paths[a][b] = NULL;
231	    }
232	
233	    list<FastflowSrc*> srcs;
234	    list<FastflowSink*> sinks;
235	
236	    uint32_t connID = 0;
237	    for (uint32_t k = 0; k < all_conns->size(); k++) {
238	        connection* crt = all_conns->at(k);
239	        uint32_t s = crt->src, d = crt->dst;
240	        connID++;
241	
242	        if (!net_paths[s][d]) net_paths[s][d] = top->get_paths(s, d);
243	        if (!net_paths[d][s]) net_paths[d][s] = top->get_paths(d, s);
244	
245	        // Pick a path via ECMP-style random hashing (deterministic seed above).
246	        uint32_t choice = rand() % net_paths[s][d]->size();
247	
248	        Route* routeout = new Route(*(net_paths[s][d]->at(choice)));
249	        Route* routein  = new Route(*(net_paths[d][s]->at(choice)));
250	
251	        FastflowSrc*  src  = new FastflowSrc(rtx_scanner, NULL, eventlist);
252	        FastflowSink* sink = new FastflowSink();
253	
254	        src->setName ("fastflow_"      + ntoa(s) + "_" + ntoa(d));
255	        sink->setName("fastflow_sink_" + ntoa(s) + "_" + ntoa(d));
256	        logfile.writeName(*src);
257	        logfile.writeName(*sink);
258	
259	        if (crt->size > 0) src->set_flowsize((uint64_t)crt->size);
260	
261	        if (use_mcc) {
262	            if (msg_target_bw <= 0.0) {
263	                // Default: assume each flow ideally gets the full link speed
264	                // (gives a hawkish-but-realistic baseline for "is the message
265	                // on schedule?"). Operator can override with -msg_target_bw.
266	                msg_target_bw = (double)linkspeed / 8.0;
267	            }
268	            src->set_msg_target_bw(msg_target_bw);
269	            src->set_msg_tolerance(msg_tolerance);
270	        }
271	
272	        if (use_credits) sink->enable_credit_mode(linkspeed);
273	
274	        // Coflow membership: by convention use crt->recv_done_trigger as the
275	        // coflow id (a non-zero value means this connection participates).
276	        // The connection-matrix file can be extended later with a dedicated
277	        // 'coflow N' token; for now this lets workloads declare coflow
278	        // membership using the existing trigger field.
279	        CoflowId cid = NO_COFLOW;
280	        if (use_coflow && crt->recv_done_trigger != 0) {
281	            cid = (CoflowId)crt->recv_done_trigger;
282	        }
283	        sink->set_coflow(cid, (SenderId)s);
284	
285	        srcs.push_back(src);
286	        sinks.push_back(sink);
287	
288	        simtime_picosec starttime = crt->trigger ? TRIGGER_START
289	                                                 : timeFromUs((uint32_t)crt->start);
290	        src->connect(*routeout, *routein, *sink, starttime);
291	
292	        if (crt->trigger) {
293	            Trigger* trig = conns->getTrigger(crt->trigger, eventlist);
294	            trig->add_target(*src);
295	        }
296	        if (crt->send_done_trigger) {
297	            Trigger* trig = conns->getTrigger(crt->send_done_trigger, eventlist);
298	            src->set_end_trigger(*trig);
299	        }
300	    }
301	
302	    cout << "[fastflow] loaded " << connID << " connections" << endl;
303	
304	    // ----- Run ---------------------------------------------------------
305	    while (eventlist.doNextEvent()) { /* spin */ }
306	
307	    cout << "[fastflow] done. simulated to "
308	         << timeAsUs(eventlist.now()) << "us" << endl;
309	
310	    // If any flow didn't finish, dump per-source state so we can debug stalls.
311	    int unfinished = 0;
312	    for (auto* src : srcs) {
313	        if (src->bytes_acked() < src->flowsize()) {
314	            if (unfinished < 10) {
315	                cout << "[fastflow] UNFINISHED " << src->nodename()
316	                     << " sent=" << src->packets_sent()
317	                     << " acked=" << src->bytes_acked()
318	                     << " flow=" << src->flowsize()
319	                     << " cwnd=" << src->cwnd()
320	                     << " rtt_us=" << timeAsUs(src->rtt())
321	                     << " drops=" << src->drops()
322	                     << " rtx=" << src->retransmits()
323	                     << " blocked=" << src->blocked_rtx()
324	                     << endl;
325	            }
326	            unfinished++;
327	        }
328	    }
329	    cout << "[fastflow] unfinished=" << unfinished << "/" << srcs.size() << endl;
330	    return 0;
331	}
