// -*- c-basic-offset: 4; indent-tabs-mode: nil -*-
//
// Entry point for the FASTFLOW simulator.
//
// Modes (selected by -mode <name>):
//   fastflow             : vanilla sender-based FASTFLOW (default).
//   fastflow+eqds        : FASTFLOW sender + EQDS-style receiver credits.
//   fastflow+eqds+mcc    : above + Message-Level CC overrides.
//   fastflow+eqds+mcc+coflow : above + asymmetric coflow credit shaping.
//
// Independently toggleable:
//   -ra_qa on|off        : Receiver-Anchored QuickAdapt (Idea 3).
//   -trimming on|off     : enable packet trimming (CompositeQueue, default on).
//
// CLI parity with main_swift.cpp is kept where possible so plot scripts and
// connection-matrix files remain interchangeable across protocols.

#include <iostream>
#include <list>
#include <math.h>
#include <sstream>
#include <string.h>

#include "config.h"
#include "eventlist.h"
#include "network.h"
#include "pipe.h"
#include "logfile.h"
#include "loggers.h"
#include "clock.h"
#include "compositequeue.h"
#include "topology.h"
#include "connection_matrix.h"
#include "fat_tree_topology.h"
#include "main.h"
#include "trigger.h"

#include "fastflow/fastflow.h"
#include "fastflow/coflow_state.h"

#define DEFAULT_NODES   128
#define DEFAULT_QUEUE_SIZE 500   // packets

EventList eventlist;
Logfile* lg;

static void exit_error(const char* progname) {
    cout << "Usage: " << progname
         << " [-tm tm-file] [-topo topo-file] [-nodes N] [-q Q] [-mtu MTU]"
         << " [-linkspeed Mbps] [-end us]"
         << " [-trimming on|off] [-plb on|off] [-ra_qa on|off]"
         << " [-mode fastflow|fastflow+eqds|fastflow+eqds+mcc|fastflow+eqds+mcc+coflow]"
         << " [-msg_target_bw Bps] [-msg_tolerance 0..1]"
         << " [-coflow_gap bytes]"
         << endl;
    exit(1);
}

static bool flag_on(const char* s) {
    return strcmp(s, "on") == 0 || strcmp(s, "true") == 0 || strcmp(s, "1") == 0;
}

int main(int argc, char** argv) {
    Clock c(timeFromSec(5.0 / 100.0), eventlist);

    uint32_t no_of_nodes = DEFAULT_NODES;
    mem_b queuesize = DEFAULT_QUEUE_SIZE;
    linkspeed_bps linkspeed = speedFromMbps((double)HOST_NIC);
    uint32_t packet_size = 4000;
    simtime_picosec endtime = timeFromMs(1.2);

    bool trimming = true;
    bool ra_qa = false;
    bool plb = true;  // paper: multi-pathing enabled for all algorithms
    bool use_credits = false;
    bool use_mcc = false;
    bool use_coflow = false;

    double msg_target_bw = 0.0;
    double msg_tolerance = 0.85;
    uint64_t coflow_gap_bytes = 4ULL * 1024 * 1024;

    const char* tm_file   = NULL;
    const char* topo_file = NULL;

    stringstream logfile_name(ios_base::out);
    logfile_name << "logout.dat";

    // ----- CLI parsing --------------------------------------------------
    int i = 1;
    while (i < argc) {
        if (!strcmp(argv[i], "-o"))            { logfile_name.str(""); logfile_name << argv[++i]; }
        else if (!strcmp(argv[i], "-nodes"))   { no_of_nodes = atoi(argv[++i]); }
        else if (!strcmp(argv[i], "-tm"))      { tm_file = argv[++i]; }
        else if (!strcmp(argv[i], "-topo"))    { topo_file = argv[++i]; }
        else if (!strcmp(argv[i], "-q"))       { queuesize = atoi(argv[++i]); }
        else if (!strcmp(argv[i], "-mtu"))     { packet_size = atoi(argv[++i]); }
        else if (!strcmp(argv[i], "-linkspeed")) { linkspeed = speedFromMbps(atof(argv[++i])); }
        else if (!strcmp(argv[i], "-end"))     { endtime = timeFromUs(atof(argv[++i])); }
        else if (!strcmp(argv[i], "-trimming")) { trimming = flag_on(argv[++i]); }
        else if (!strcmp(argv[i], "-plb"))     { plb = flag_on(argv[++i]); }
        else if (!strcmp(argv[i], "-ra_qa"))   { ra_qa = flag_on(argv[++i]); }
        else if (!strcmp(argv[i], "-mode")) {
            const char* m = argv[++i];
            if (!strcmp(m, "fastflow")) {
                use_credits = false; use_mcc = false; use_coflow = false;
            } else if (!strcmp(m, "fastflow+eqds")) {
                use_credits = true;  use_mcc = false; use_coflow = false;
            } else if (!strcmp(m, "fastflow+eqds+mcc")) {
                use_credits = true;  use_mcc = true;  use_coflow = false;
            } else if (!strcmp(m, "fastflow+eqds+mcc+coflow")) {
                use_credits = true;  use_mcc = true;  use_coflow = true;
            } else {
                cerr << "Unknown mode '" << m << "'\n"; exit_error(argv[0]);
            }
        }
        else if (!strcmp(argv[i], "-msg_target_bw")) { msg_target_bw = atof(argv[++i]); }
        else if (!strcmp(argv[i], "-msg_tolerance")) { msg_tolerance = atof(argv[++i]); }
        else if (!strcmp(argv[i], "-coflow_gap"))    { coflow_gap_bytes = strtoull(argv[++i], NULL, 10); }
        else { exit_error(argv[0]); }
        i++;
    }

    Packet::set_packet_size(packet_size);
    eventlist.setEndtime(endtime);
    queuesize = queuesize * Packet::data_packet_size();
    srand(13);

    // ----- Wire FASTFLOW global toggles --------------------------------
    FastflowSrc::_mtu = packet_size;
    FastflowSrc::_enable_ra_qa = ra_qa;
    FastflowSrc::_enable_credits = use_credits;
    FastflowSrc::_enable_mcc = use_mcc;
    FastflowSrc::_trim_supported = trimming;
    if (!trimming) FastflowSrc::_md_const = 4.0;

    CoflowRegistry::instance().reset();
    if (use_coflow) {
        CoflowRegistry::instance().set_policy(COFLOW_ASYMMETRIC);
        CoflowRegistry::instance().set_gap_threshold(coflow_gap_bytes);
    }

    cout << "[fastflow] mode "
         << (use_credits ? (use_mcc ? (use_coflow ? "fastflow+eqds+mcc+coflow"
                                                  : "fastflow+eqds+mcc")
                                    : "fastflow+eqds")
                         : "fastflow")
         << " trimming=" << trimming
         << " plb="      << plb
         << " ra_qa="    << ra_qa
         << " mtu="      << packet_size
         << " nodes="    << no_of_nodes
         << " linkspeed=" << (linkspeed / 1000000) << " Mbps"
         << endl;

    Logfile logfile(logfile_name.str(), eventlist);
    lg = &logfile;
    logfile.setStartTime(timeFromSec(0));

    // ----- Topology -----------------------------------------------------
    FatTreeTopology* top;
    queue_type net_qt    = trimming ? COMPOSITE : RANDOM;
    queue_type sender_qt = FAIR_PRIO;
    if (topo_file) {
        top = FatTreeTopology::load(topo_file, NULL, eventlist, queuesize,
                                    net_qt, sender_qt);
    } else {
        top = new FatTreeTopology(no_of_nodes, linkspeed, queuesize,
                                  NULL, &eventlist, NULL, net_qt, sender_qt, 0);
    }
    no_of_nodes = top->no_of_nodes();
    cout << "[fastflow] actual nodes " << no_of_nodes << endl;

    // ----- Derive FASTFLOW parameters from the topology -----------------
    //
    // Per paper Sec 3.5:
    //   base_rtt is the empty-network RTT (2 * link_latency * hops + queuing-free
    //     switch traversal). At 800Gbps with hop_latency ~600ns and 3 tier
    //     traversal, we approximate base_rtt = 12us. For correctness we set
    //     it from queuesize/linkspeed-derived BDP.
    //   target_rtt = 1.5 * base_rtt
    //   fi, mi scaled by gamma = bdp / reference_bdp (100Gbps,12us)
    //
    // We use 12us as the reference because the FASTFLOW paper uses that.

    simtime_picosec brtt = timeFromUs((uint32_t)12);
    simtime_picosec trtt = (brtt * 3) / 2;
    uint64_t bdp_bytes = (uint64_t)((double)linkspeed * timeAsSec(brtt) / 8.0);
    uint64_t reference_bdp = (uint64_t)((double)speedFromMbps(100000.0) * timeAsSec(timeFromUs((uint32_t)12)) / 8.0);
    double gamma = (double)bdp_bytes / (double)reference_bdp;

    FastflowSrc::_base_rtt   = brtt;
    FastflowSrc::_target_rtt = trtt;
    FastflowSrc::_bdp_bytes  = (uint32_t)bdp_bytes;
    FastflowSrc::_fi_const   = 0.25 * gamma;
    // mi is recomputed per-call inside multiplicative_increase but uses
    // _base_rtt and _target_rtt which we just set.
    FastflowSrc::_fd_const   = 0.8;
    FastflowSrc::_md_const   = trimming ? 2.0 : 4.0;
    FastflowSrc::_qa_scaling = 0.8;
    FastflowSrc::_wtd_alpha  = 0.125;
    FastflowSrc::_wtd_thresh = 0.25;
    FastflowSrc::_k_fastinc  = 2;

    cout << "[fastflow] brtt=" << timeAsUs(brtt) << "us trtt=" << timeAsUs(trtt) << "us"
         << " bdp=" << bdp_bytes << "B gamma=" << gamma << endl;

    // ----- Connection matrix --------------------------------------------
    ConnectionMatrix* conns = new ConnectionMatrix(no_of_nodes);
    if (tm_file) {
        cout << "[fastflow] loading traffic matrix " << tm_file << endl;
        if (!conns->load(tm_file)) exit(-1);
    } else {
        cout << "[fastflow] reading traffic matrix from stdin" << endl;
        conns->load(cin);
    }
    if (conns->N != no_of_nodes) {
        cerr << "[fastflow] tm nodes " << conns->N
             << " != topology nodes " << no_of_nodes << endl;
        exit(-1);
    }

    // ----- Flow construction --------------------------------------------
    // RTO scan period must be much shorter than typical RTO so a stuck
    // hole (e.g. because the trim ACK was truly dropped in the fabric)
    // gets recovered within a few RTTs — not after 10ms.
    FastflowRtxTimerScanner rtx_scanner(timeFromUs((uint32_t)50), eventlist);

    vector<connection*>* all_conns = conns->getAllConnections();
    vector<const Route*>*** net_paths = new vector<const Route*>**[no_of_nodes];
    for (uint32_t a = 0; a < no_of_nodes; a++) {
        net_paths[a] = new vector<const Route*>*[no_of_nodes];
        for (uint32_t b = 0; b < no_of_nodes; b++) net_paths[a][b] = NULL;
    }

    list<FastflowSrc*> srcs;
    list<FastflowSink*> sinks;

    uint32_t connID = 0;
    for (uint32_t k = 0; k < all_conns->size(); k++) {
        connection* crt = all_conns->at(k);
        uint32_t s = crt->src, d = crt->dst;
        connID++;

        if (!net_paths[s][d]) net_paths[s][d] = top->get_paths(s, d);
        if (!net_paths[d][s]) net_paths[d][s] = top->get_paths(d, s);

        // Pick a path via ECMP-style random hashing (deterministic seed above).
        uint32_t choice = rand() % net_paths[s][d]->size();

        Route* routeout = new Route(*(net_paths[s][d]->at(choice)));
        Route* routein  = new Route(*(net_paths[d][s]->at(choice)));

        FastflowSrc*  src  = new FastflowSrc(rtx_scanner, NULL, eventlist);
        FastflowSink* sink = new FastflowSink();

        // Give the src all ECMP paths so PLB can switch between them at runtime.
        src->set_paths(net_paths[s][d]);
        if (plb) src->enable_plb();

        src->setName ("fastflow_"      + ntoa(s) + "_" + ntoa(d));
        sink->setName("fastflow_sink_" + ntoa(s) + "_" + ntoa(d));
        logfile.writeName(*src);
        logfile.writeName(*sink);

        if (crt->size > 0) src->set_flowsize((uint64_t)crt->size);

        if (use_mcc) {
            if (msg_target_bw <= 0.0) {
                // Default: assume each flow ideally gets the full link speed
                // (gives a hawkish-but-realistic baseline for "is the message
                // on schedule?"). Operator can override with -msg_target_bw.
                msg_target_bw = (double)linkspeed / 8.0;
            }
            src->set_msg_target_bw(msg_target_bw);
            src->set_msg_tolerance(msg_tolerance);
        }

        if (use_credits) sink->enable_credit_mode(linkspeed);

        // Coflow membership: by convention use crt->recv_done_trigger as the
        // coflow id (a non-zero value means this connection participates).
        // The connection-matrix file can be extended later with a dedicated
        // 'coflow N' token; for now this lets workloads declare coflow
        // membership using the existing trigger field.
        CoflowId cid = NO_COFLOW;
        if (use_coflow && crt->recv_done_trigger != 0) {
            cid = (CoflowId)crt->recv_done_trigger;
        }
        sink->set_coflow(cid, (SenderId)s);

        srcs.push_back(src);
        sinks.push_back(sink);

        simtime_picosec starttime = crt->trigger ? TRIGGER_START
                                                 : timeFromUs((uint32_t)crt->start);
        src->connect(*routeout, *routein, *sink, starttime);

        if (crt->trigger) {
            Trigger* trig = conns->getTrigger(crt->trigger, eventlist);
            trig->add_target(*src);
        }
        if (crt->send_done_trigger) {
            Trigger* trig = conns->getTrigger(crt->send_done_trigger, eventlist);
            src->set_end_trigger(*trig);
        }
    }

    cout << "[fastflow] loaded " << connID << " connections" << endl;

    // ----- Run ---------------------------------------------------------
    while (eventlist.doNextEvent()) { /* spin */ }

    cout << "[fastflow] done. simulated to "
         << timeAsUs(eventlist.now()) << "us" << endl;

    // If any flow didn't finish, dump per-source state so we can debug stalls.
    int unfinished = 0;
    for (auto* src : srcs) {
        if (src->bytes_acked() < src->flowsize()) {
            if (unfinished < 10) {
                cout << "[fastflow] UNFINISHED " << src->nodename()
                     << " sent=" << src->packets_sent()
                     << " acked=" << src->bytes_acked()
                     << " flow=" << src->flowsize()
                     << " cwnd=" << src->cwnd()
                     << " rtt_us=" << timeAsUs(src->rtt())
                     << " drops=" << src->drops()
                     << " rtx=" << src->retransmits()
                     << " blocked=" << src->blocked_rtx()
                     << endl;
            }
            unfinished++;
        }
    }
    cout << "[fastflow] unfinished=" << unfinished << "/" << srcs.size() << endl;
    return 0;
}

// -*- c-basic-offset: 4; indent-tabs-mode: nil -*-
//
// FASTFLOW: sender-based CC using ECN + RTT + packet trimming.
// Implements the algorithm from Bonato et al. 2024 (arXiv 2404.01630),
// reproduced and extended for this codebase.
//
// Layered features (all togglable via static flags so a single source/sink
// class covers every variant the paper plan needs):
//   - FASTFLOW core: paper Algorithm 1 (FD/MD/FI/MI), Algorithm 2 (QuickAdapt),
//                    Algorithm 3 (FastIncrease), Sec 3.5.1 (Wait-to-Decrease).
//   - Idea 1: receiver credits + Message-Level CC overrides.
//   - Idea 2: coflow-aware asymmetric credit allocation (state on the sink).
//   - Idea 3: Receiver-Anchored QuickAdapt — sink stamps its own
//             bytes-received-per-trtt onto each ACK, sender uses that
//             directly when QuickAdapt fires.

#ifndef FASTFLOW_H
#define FASTFLOW_H

#include <list>
#include <map>
#include <set>
#include <vector>
#include <string>

#include "config.h"
#include "network.h"
#include "eventlist.h"
#include "loggertypes.h"
#include "trigger.h"

#include "fastflowpacket.h"
#include "coflow_state.h"

class FastflowSink;
class FastflowSrc;
class FastflowRtxTimerScanner;
class FastflowPacer;

// ===========================================================================
// FastflowPacer — runs the source in paced mode when cwnd drops below 1 MTU.
// ===========================================================================
class FastflowPacer : public EventSource {
public:
    FastflowPacer(FastflowSrc& src, EventList& eventlist);
    bool is_pending() const { return _interpacket_delay > 0; }
    void schedule_send(simtime_picosec delay);
    void cancel();
    void just_sent();
    virtual void doNextEvent();

private:
    FastflowSrc* _src;
    simtime_picosec _interpacket_delay;
    simtime_picosec _last_send;
    simtime_picosec _next_send;
};

// ===========================================================================
// FastflowSrc — the sender.
// ===========================================================================
class FastflowSrc : public EventSource, public PacketSink, public TriggerTarget {
    friend class FastflowSink;
    friend class FastflowPacer;
    friend class FastflowRtxTimerScanner;

public:
    FastflowSrc(FastflowRtxTimerScanner& rtx_scanner,
                TrafficLogger* pktlogger, EventList& eventlist);

    void connect(const Route& routeout, const Route& routeback,
                 FastflowSink& sink, simtime_picosec starttime);
    virtual void receivePacket(Packet& pkt);
    virtual void doNextEvent();
    virtual const string& nodename() { return _nodename; }
    PacketFlow& flow() { return _flow; }

    // Trigger interface
    virtual void activate();
    void set_end_trigger(Trigger& trigger);

    // Workload config
    void set_flowsize(uint64_t bytes);
    uint64_t flowsize() const { return _flow_size; }
    void set_paths(vector<const Route*>* rt);
    void enable_plb() { _plb = true; }

    // ====================== Global tunables (paper Sec 3.5) ================
    static uint16_t _mtu;          // MTU in bytes (data packet payload)
    static double   _fd_const;     // Fair decrease constant (0.8)
    static double   _fi_const;     // Fair increase constant (0.25 at 100Gbps ref)
    static double   _md_const;     // Multiplicative decrease constant (2; 4 if no trim)
    static double   _qa_scaling;   // QuickAdapt window scale (0.8)
    static double   _wtd_alpha;    // EMA constant for WTD (0.125)
    static double   _wtd_thresh;   // WTD trigger threshold (0.25)
    static uint32_t _k_fastinc;    // packets per FastIncrease step (2)
    static simtime_picosec _base_rtt;     // base RTT for the topology
    static simtime_picosec _target_rtt;   // 1.5 * base_rtt (paper default)
    static uint32_t _bdp_bytes;    // BDP in bytes for cwnd clamp

    // ====================== Feature toggles (CLI-driven) ===================
    static bool _enable_ra_qa;     // Idea 3: receiver-anchored QuickAdapt
    static bool _enable_credits;   // Idea 1: gate sends on receiver credits
    static bool _enable_mcc;       // Idea 1: message-level CC override
    static bool _trim_supported;   // if false, double _md and rely on timeouts

    // For workload-aware MCC: target bandwidth per flow (bytes/sec)
    void set_msg_target_bw(double bytes_per_sec) { _msg_target_bw = bytes_per_sec; }
    void set_msg_tolerance(double t)             { _msg_tolerance = t; }
    bool message_is_healthy(simtime_picosec now) const;

    // Stats
    uint64_t packets_sent() const { return _packets_sent; }
    uint64_t bytes_acked()  const { return _last_acked; }
    uint64_t retransmits()  const { return _retransmits_dbg; }
    uint64_t blocked_rtx()  const { return _blocked_rtx_dbg; }

    // ====================== Internal accessors for debugging ==============
    uint32_t cwnd() const { return _cwnd; }
    simtime_picosec rtt() const { return _rtt; }
    uint32_t drops() const { return _drops; }

protected:
    // --- Connectivity ---
    bool _established;
    const Route* _route;          // outbound route (sender -> sink)
    FastflowSink* _sink;
    PacketFlow _flow;
    vector<const Route*> _paths;  // ECMP path pool
    uint32_t _path_index;
    bool _plb;                          // PLB enabled
    simtime_picosec _plb_last_good;     // timestamp of last congestion-free ACK
    simtime_picosec _plb_interval;      // retry-path interval (randomised)

    // --- Sending state ---
    uint64_t _highest_sent;       // highest seqno ever sent (bytes)
    uint64_t _last_acked;         // cumulative ack point
    uint64_t _flow_size;          // total bytes to send
    uint64_t _packets_sent;       // counter for stats

    // --- Core FASTFLOW state (paper Algo 1) ---
    uint32_t _cwnd;               // congestion window (bytes)
    uint64_t _acked;              // bytes acked in current QuickAdapt window
    uint64_t _bytes_ignored;      // accumulator for post-QA grace
    uint64_t _bytes_to_ignore;    // ignore-budget after QuickAdapt fires
    bool     _trigger_qa;         // a trim/timeout has armed QuickAdapt
    double   _avg_wtd;            // EMA of ECN markings for Wait-to-Decrease
    uint32_t _fast_inc_count;     // bytes of clean ACKs in current FI window
    bool     _in_fast_inc;        // FastIncrease currently active
    simtime_picosec _qa_end;      // earliest time a new QuickAdapt may fire
    simtime_picosec _last_decrease;

    // --- RTT/RTO ---
    simtime_picosec _rtt, _rto, _mdev;
    simtime_picosec _min_rto;
    simtime_picosec _RFC2988_RTO_timeout;
    bool _rtx_timeout_pending;
    uint32_t _retransmit_cnt;
    uint32_t _drops;

    // --- Retransmission dedup + deferred retry ---
    // Trim ACKs retransmit the trimmed seqno immediately (paper Algo 1).
    // _rtx_blockuntil holds (seqno -> earliest-next-retransmit-time) so a
    // single dropped packet that gets trimmed several times in quick
    // succession only triggers one retransmit per RTT. When a trim arrives
    // for a seqno whose block has not expired we stash it in _rtx_pending
    // and drain it on the next event whose timestamp clears the block —
    // otherwise blocked trims would be silently lost between block-expiry
    // and the next RTO fire (which happens at a much coarser cadence).
    std::map<FastflowPacket::seq_t, simtime_picosec> _rtx_blockuntil;
    std::set<FastflowPacket::seq_t> _rtx_pending;
    uint64_t _retransmits_dbg;
    uint64_t _blocked_rtx_dbg;

    // --- Idea 1: credits + MCC ---
    uint64_t _initial_burst_remaining;  // 1 BDP blind send before credits
    uint64_t _receiver_credits;         // bytes the sink has authorised
    simtime_picosec _msg_start_time;
    uint64_t _msg_acked;                // bytes acked since msg start
    double   _msg_target_bw;            // bytes/sec the message expects
    double   _msg_tolerance;            // healthy if acked >= elapsed*bw*tol

    // --- FCT bookkeeping ---
    simtime_picosec _start_time;
    bool _flow_finished;
    Trigger* _end_trigger;

    // Pacer (used when cwnd < 1 MTU)
    FastflowPacer _pacer;
    simtime_picosec _pacing_delay;

    // Logging
    TrafficLogger* _traffic_logger;
    string _nodename;
    FastflowRtxTimerScanner* _rtx_scanner;

private:
    // --- Control loop (Algorithm 1) ---
    void handle_ack(FastflowAck& ack);
    bool wait_to_decrease(bool ecn, simtime_picosec now);
    bool quick_adapt(FastflowAck& ack, simtime_picosec now);
    bool fast_increase(FastflowAck& ack);
    void fair_decrease(uint16_t pkt_size);
    void multiplicative_decrease(uint16_t pkt_size, simtime_picosec rtt_sample);
    void fair_increase(uint16_t pkt_size);
    void multiplicative_increase(uint16_t pkt_size, simtime_picosec rtt_sample);
    void clamp_cwnd();
    void update_rtt(simtime_picosec sample);

    // --- Sending ---
    int  send_packets();
    bool send_next_packet();
    void retransmit_packet();
    void send_syn();
    bool can_send_one_mtu() const;     // checks credits + cwnd

    // --- Trim / timeout reaction (Algo 1 lines 28-34) ---
    void handle_trim(FastflowAck& ack);
    void retransmit_seqno(FastflowPacket::seq_t seqno);
    void drain_pending_rtx();
    void prune_blockuntil();
    bool can_retransmit(FastflowPacket::seq_t seqno) const;
    void rtx_timer_hook(simtime_picosec now, simtime_picosec period);

    // --- Completion ---
    void maybe_report_completion();

    void startflow();
};

// ===========================================================================
// FastflowSink — the receiver.
// ===========================================================================
class FastflowSink : public PacketSink, public Logged {
    friend class FastflowSrc;

public:
    FastflowSink();
    virtual void receivePacket(Packet& pkt);
    virtual const string& nodename() { return _nodename; }
    void connect(FastflowSrc& src, const Route& routeback);
    virtual void setName(const string& name) { Logged::setName(name); _nodename = name; }

    // Idea 2: register this sink as part of a coflow.
    void set_coflow(CoflowId cid, SenderId sid);

    // Idea 1: credit-grant emission (called periodically when credits enabled).
    void enable_credit_mode(linkspeed_bps host_linkspeed);
    void issue_credit_if_due(simtime_picosec now);

    uint64_t cumulative_ack() const { return _cumulative_ack; }
    uint32_t drops()          const { return _drops; }

protected:
    FastflowSrc* _src;
    const Route* _route_back;
    string _nodename;

    // ACK state
    uint64_t _cumulative_ack;          // last contiguous byte
    std::list<FastflowPacket::seq_t> _received;  // out-of-order holes
    uint32_t _drops;

    // RA-QA window
    uint64_t _bytes_received_window;       // current (possibly partial) window
    uint64_t _bytes_received_last_window;  // previous completed window (stable)
    simtime_picosec _window_start;

    // Credit mode (Idea 1)
    bool _credit_mode;
    linkspeed_bps _host_linkspeed;
    simtime_picosec _next_credit_time;
    uint32_t _credit_quantum;          // default ~1 MTU per RTT/N

    // Coflow membership (Idea 2)
    CoflowId _coflow_id;
    SenderId _sender_id;
    uint64_t _bytes_received_total;    // for coflow progress tracking

private:
    void send_ack(FastflowPacket& pkt, bool trimmed, simtime_picosec now);
    void update_recv_window(uint32_t pkt_size, simtime_picosec now);
};

// ===========================================================================
// FastflowRtxTimerScanner — periodic scan to fire RTOs.
// ===========================================================================
class FastflowRtxTimerScanner : public EventSource {
public:
    FastflowRtxTimerScanner(simtime_picosec scanPeriod, EventList& eventlist);
    virtual void doNextEvent();
    void registerSrc(FastflowSrc& src);
    void deregisterSrc(FastflowSrc& src);

private:
    simtime_picosec _scanPeriod;
    std::list<FastflowSrc*> _srcs;
};

#endif // FASTFLOW_H

skills.content:
# Update Config Skill

Modify Claude Code configuration by updating settings.json files.

## When Hooks Are Required (Not Memory)

If the user wants something to happen automatically in response to an EVENT, they need a **hook** configured in settings.json. Memory/preferences cannot trigger automated actions.

**These require hooks:**
- "Before compacting, ask me what to preserve" → PreCompact hook
- "After writing files, run prettier" → PostToolUse hook with Write|Edit matcher
- "When I run bash commands, log them" → PreToolUse hook with Bash matcher
- "Always run tests after code changes" → PostToolUse hook

**Hook events:** PreToolUse, PostToolUse, PreCompact, PostCompact, Stop, Notification, SessionStart

## CRITICAL: Read Before Write

**Always read the existing settings file before making changes.** Merge new settings with existing ones - never replace the entire file.

## CRITICAL: Use AskUserQuestion for Ambiguity

When the user's request is ambiguous, use AskUserQuestion to clarify:
- Which settings file to modify (user/project/local)
- Whether to add to existing arrays or replace them
- Specific values when multiple options exist

## Decision: /config command vs Direct Edit

**Suggest the `/config` slash command** for these simple settings:
- `theme`, `editorMode`, `verbose`, `model`
- `language`, `alwaysThinkingEnabled`
- `permissions.defaultMode`

**Edit settings.json directly** for:
- Hooks (PreToolUse, PostToolUse, etc.)
- Complex permission rules (allow/deny arrays)
- Environment variables
- MCP server configuration
- Plugin configuration

## Workflow

1. **Clarify intent** - Ask if the request is ambiguous
2. **Read existing file** - Use Read tool on the target settings file
3. **Merge carefully** - Preserve existing settings, especially arrays
4. **Edit file** - Use Edit tool (if file doesn't exist, ask user to create it first)
5. **Confirm** - Tell user what was changed

## Merging Arrays (Important!)

When adding to permission arrays or hook arrays, **merge with existing**, don't replace:

**WRONG** (replaces existing permissions):
```json
{ "permissions": { "allow": ["Bash(npm *)"] } }
```

**RIGHT** (preserves existing + adds new):
```json
{
  "permissions": {
    "allow": [
      "Bash(git *)",      // existing
      "Edit(.claude)",    // existing
      "Bash(npm *)"       // new
    ]
  }
}
```

## Settings File Locations

Choose the appropriate file based on scope:

| File | Scope | Git | Use For |
|------|-------|-----|---------|
| `~/.claude/settings.json` | Global | N/A | Personal preferences for all projects |
| `.claude/settings.json` | Project | Commit | Team-wide hooks, permissions, plugins |
| `.claude/settings.local.json` | Project | Gitignore | Personal overrides for this project |

Settings load in order: user → project → local (later overrides earlier).

## Settings Schema Reference

### Permissions
```json
{
  "permissions": {
    "allow": ["Bash(npm *)", "Edit(.claude)", "Read"],
    "deny": ["Bash(rm -rf *)"],
    "ask": ["Write(/etc/*)"],
    "defaultMode": "default" | "plan" | "acceptEdits" | "dontAsk",
    "additionalDirectories": ["/extra/dir"]
  }
}
```

**Permission Rule Syntax:**
- Exact match: `"Bash(npm run test)"`
- Prefix wildcard: `"Bash(git *)"` - matches `git`, `git status`, `git commit`, etc.
- Tool only: `"Read"` - allows all Read operations

### Environment Variables
```json
{
  "env": {
    "DEBUG": "true",
    "MY_API_KEY": "value"
  }
}
```

### Model & Agent
```json
{
  "model": "sonnet",  // or "opus", "haiku", full model ID
  "agent": "agent-name",
  "alwaysThinkingEnabled": true
}
```

### Attribution (Commits & PRs)
```json
{
  "attribution": {
    "commit": "Custom commit trailer text",
    "pr": "Custom PR description text"
  }
}
```
Set `commit` or `pr` to empty string `""` to hide that attribution.

### MCP Server Management
```json
{
  "enableAllProjectMcpServers": true,
  "enabledMcpjsonServers": ["server1", "server2"],
  "disabledMcpjsonServers": ["blocked-server"]
}
```

### Plugins
```json
{
  "enabledPlugins": {
    "formatter@anthropic-tools": true
  }
}
```
Plugin syntax: `plugin-name@source` where source is `claude-code-marketplace`, `claude-plugins-official`, or `builtin`.

### Other Settings
- `language`: Preferred response language (e.g., "japanese")
- `cleanupPeriodDays`: Days to keep transcripts before automatic cleanup (default: 30; minimum 1)
- `respectGitignore`: Whether to respect .gitignore (default: true)
- `spinnerTipsEnabled`: Show tips in spinner
- `spinnerVerbs`: Customize spinner verbs (`{ "mode": "append" | "replace", "verbs": [...] }`)
- `spinnerTipsOverride`: Override spinner tips (`{ "excludeDefault": true, "tips": ["Custom tip"] }`)
- `syntaxHighlightingDisabled`: Disable diff highlighting


## Hooks Configuration

Hooks run commands at specific points in Claude Code's lifecycle.

### Hook Structure
```json
{
  "hooks": {
    "EVENT_NAME": [
      {
        "matcher": "ToolName|OtherTool",
        "hooks": [
          {
            "type": "command",
            "command": "your-command-here",
            "timeout": 60,
            "statusMessage": "Running..."
          }
        ]
      }
    ]
  }
}
```

### Hook Events

| Event | Matcher | Purpose |
|-------|---------|---------|
| PermissionRequest | Tool name | Run before permission prompt |
| PreToolUse | Tool name | Run before tool, can block |
| PostToolUse | Tool name | Run after successful tool |
| PostToolUseFailure | Tool name | Run after tool fails |
| Notification | Notification type | Run on notifications |
| Stop | - | Run when Claude stops (including clear, resume, compact) |
| PreCompact | "manual"/"auto" | Before compaction |
| PostCompact | "manual"/"auto" | After compaction (receives summary) |
| UserPromptSubmit | - | When user submits |
| SessionStart | - | When session starts |

**Common tool matchers:** `Bash`, `Write`, `Edit`, `Read`, `Glob`, `Grep`

### Hook Types

**1. Command Hook** - Runs a shell command:
```json
{ "type": "command", "command": "prettier --write $FILE", "timeout": 30 }
```

**2. Prompt Hook** - Evaluates a condition with LLM:
```json
{ "type": "prompt", "prompt": "Is this safe? $ARGUMENTS" }
```
Only available for tool events: PreToolUse, PostToolUse, PermissionRequest.

**3. Agent Hook** - Runs an agent with tools:
```json
{ "type": "agent", "prompt": "Verify tests pass: $ARGUMENTS" }
```
Only available for tool events: PreToolUse, PostToolUse, PermissionRequest.

### Hook Input (stdin JSON)
```json
{
  "session_id": "abc123",
  "tool_name": "Write",
  "tool_input": { "file_path": "/path/to/file.txt", "content": "..." },
  "tool_response": { "success": true }  // PostToolUse only
}
```

### Hook JSON Output

Hooks can return JSON to control behavior:

```json
{
  "systemMessage": "Warning shown to user in UI",
  "continue": false,
  "stopReason": "Message shown when blocking",
  "suppressOutput": false,
  "decision": "block",
  "reason": "Explanation for decision",
  "hookSpecificOutput": {
    "hookEventName": "PostToolUse",
    "additionalContext": "Context injected back to model"
  }
}
```

**Fields:**
- `systemMessage` - Display a message to the user (all hooks)
- `continue` - Set to `false` to block/stop (default: true)
- `stopReason` - Message shown when `continue` is false
- `suppressOutput` - Hide stdout from transcript (default: false)
- `decision` - "block" for PostToolUse/Stop/UserPromptSubmit hooks (deprecated for PreToolUse, use hookSpecificOutput.permissionDecision instead)
- `reason` - Explanation for decision
- `hookSpecificOutput` - Event-specific output (must include `hookEventName`):
  - `additionalContext` - Text injected into model context
  - `permissionDecision` - "allow", "deny", or "ask" (PreToolUse only)
  - `permissionDecisionReason` - Reason for the permission decision (PreToolUse only)
  - `updatedInput` - Modified tool input (PreToolUse only)

### Common Patterns

**Auto-format after writes:**
```json
{
  "hooks": {
    "PostToolUse": [{
      "matcher": "Write|Edit",
      "hooks": [{
        "type": "command",
        "command": "jq -r '.tool_response.filePath // .tool_input.file_path' | { read -r f; prettier --write \"$f\"; } 2>/dev/null || true"
      }]
    }]
  }
}
```

**Log all bash commands:**
```json
{
  "hooks": {
    "PreToolUse": [{
      "matcher": "Bash",
      "hooks": [{
        "type": "command",
        "command": "jq -r '.tool_input.command' >> ~/.claude/bash-log.txt"
      }]
    }]
  }
}
```

**Stop hook that displays message to user:**

Command must output JSON with `systemMessage` field:
```bash
# Example command that outputs: {"systemMessage": "Session complete!"}
echo '{"systemMessage": "Session complete!"}'
```

**Run tests after code changes:**
```json
{
  "hooks": {
    "PostToolUse": [{
      "matcher": "Write|Edit",
      "hooks": [{
        "type": "command",
        "command": "jq -r '.tool_input.file_path // .tool_response.filePath' | grep -E '\\.(ts|js)$' && npm test || true"
      }]
    }]
  }
}
```


## Constructing a Hook (with verification)

Given an event, matcher, target file, and desired behavior, follow this flow. Each step catches a different failure class — a hook that silently does nothing is worse than no hook.

1. **Dedup check.** Read the target file. If a hook already exists on the same event+matcher, show the existing command and ask: keep it, replace it, or add alongside.

2. **Construct the command for THIS project — don't assume.** The hook receives JSON on stdin. Build a command that:
   - Extracts any needed payload safely — use `jq -r` into a quoted variable or `{ read -r f; ... "$f"; }`, NOT unquoted `| xargs` (splits on spaces)
   - Invokes the underlying tool the way this project runs it (npx/bunx/yarn/pnpm? Makefile target? globally-installed?)
   - Skips inputs the tool doesn't handle (formatters often have `--ignore-unknown`; if not, guard by extension)
   - Stays RAW for now — no `|| true`, no stderr suppression. You'll wrap it after the pipe-test passes.

3. **Pipe-test the raw command.** Synthesize the stdin payload the hook will receive and pipe it directly:
   - `Pre|PostToolUse` on `Write|Edit`: `echo '{"tool_name":"Edit","tool_input":{"file_path":"<a real file from this repo>"}}' | <cmd>`
   - `Pre|PostToolUse` on `Bash`: `echo '{"tool_name":"Bash","tool_input":{"command":"ls"}}' | <cmd>`
   - `Stop`/`UserPromptSubmit`/`SessionStart`: most commands don't read stdin, so `echo '{}' | <cmd>` suffices

   Check exit code AND side effect (file actually formatted, test actually ran). If it fails you get a real error — fix (wrong package manager? tool not installed? jq path wrong?) and retest. Once it works, wrap with `2>/dev/null || true` (unless the user wants a blocking check).

4. **Write the JSON.** Merge into the target file (schema shape in the "Hook Structure" section above). If this creates `.claude/settings.local.json` for the first time, add it to .gitignore — the Write tool doesn't auto-gitignore it.

5. **Validate syntax + schema in one shot:**

   `jq -e '.hooks.<event>[] | select(.matcher == "<matcher>") | .hooks[] | select(.type == "command") | .command' <target-file>`

   Exit 0 + prints your command = correct. Exit 4 = matcher doesn't match. Exit 5 = malformed JSON or wrong nesting. A broken settings.json silently disables ALL settings from that file — fix any pre-existing malformation too.

6. **Prove the hook fires** — only for `Pre|PostToolUse` on a matcher you can trigger in-turn (`Write|Edit` via Edit, `Bash` via Bash). `Stop`/`UserPromptSubmit`/`SessionStart` fire outside this turn — skip to step 7.

   For a **formatter** on `PostToolUse`/`Write|Edit`: introduce a detectable violation via Edit (two consecutive blank lines, bad indentation, missing semicolon — something this formatter corrects; NOT trailing whitespace, Edit strips that before writing), re-read, confirm the hook **fixed** it. For **anything else**: temporarily prefix the command in settings.json with `echo "$(date) hook fired" >> /tmp/claude-hook-check.txt; `, trigger the matching tool (Edit for `Write|Edit`, a harmless `true` for `Bash`), read the sentinel file.

   **Always clean up** — revert the violation, strip the sentinel prefix — whether the proof passed or failed.

   **If proof fails but pipe-test passed and `jq -e` passed**: the settings watcher isn't watching `.claude/` — it only watches directories that had a settings file when this session started. The hook is written correctly. Tell the user to open `/hooks` once (reloads config) or restart — you can't do this yourself; `/hooks` is a user UI menu and opening it ends this turn.

7. **Handoff.** Tell the user the hook is live (or needs `/hooks`/restart per the watcher caveat). Point them at `/hooks` to review, edit, or disable it later. The UI only shows "Ran N hooks" if a hook errors or is slow — silent success is invisible by design.


## Example Workflows

### Adding a Hook

User: "Format my code after Claude writes it"

1. **Clarify**: Which formatter? (prettier, gofmt, etc.)
2. **Read**: `.claude/settings.json` (or create if missing)
3. **Merge**: Add to existing hooks, don't replace
4. **Result**:
```json
{
  "hooks": {
    "PostToolUse": [{
      "matcher": "Write|Edit",
      "hooks": [{
        "type": "command",
        "command": "jq -r '.tool_response.filePath // .tool_input.file_path' | { read -r f; prettier --write \"$f\"; } 2>/dev/null || true"
      }]
    }]
  }
}
```

### Adding Permissions

User: "Allow npm commands without prompting"

1. **Read**: Existing permissions
2. **Merge**: Add `Bash(npm *)` to allow array
3. **Result**: Combined with existing allows

### Environment Variables

User: "Set DEBUG=true"

1. **Decide**: User settings (global) or project settings?
2. **Read**: Target file
3. **Merge**: Add to env object
```json
{ "env": { "DEBUG": "true" } }
```

## Common Mistakes to Avoid

1. **Replacing instead of merging** - Always preserve existing settings
2. **Wrong file** - Ask user if scope is unclear
3. **Invalid JSON** - Validate syntax after changes
4. **Forgetting to read first** - Always read before write

## Troubleshooting Hooks

If a hook isn't running:
1. **Check the settings file** - Read ~/.claude/settings.json or .claude/settings.json
2. **Verify JSON syntax** - Invalid JSON silently fails
3. **Check the matcher** - Does it match the tool name? (e.g., "Bash", "Write", "Edit")
4. **Check hook type** - Is it "command", "prompt", or "agent"?
5. **Test the command** - Run the hook command manually to see if it works
6. **Use --debug** - Run `claude --debug` to see hook execution logs


