import os

def load_fct(path):
    data = []
    try:
        with open(path) as f:
            for line in f:
                parts = line.split()
                if len(parts) == 10 and parts[0] == 'FCT':
                    data.append(float(parts[7]))
    except:
        return []
    data.sort()
    return data

def pstats(data):
    if not data:
        return None
    n = len(data)
    return {'n': n, 'p50': data[n//2], 'p99': data[int(n*0.99)], 'max': data[-1], 'mean': sum(data)/n}

PROTO_DIRS = {'swift': 'swift', 'fastflow': 'fastflow', 'fastflow+eqds': 'fastflow_eqds', 'fastflow+eqds+mcc': 'fastflow_eqds_mcc'}
LINKSPEED_BPS = 800e9

print('=== INCAST (non-blocking, PLB on) ===')
