                s = pstats(d)
                print(f'  {proto:30s} {siz}KiB: n={s[\"n\"]:3d}/{deg}  p99={s[\"p99\"]:8.1f}us  max={s[\"max\"]:8.1f}us  ({s[\"max\"]/ideal:.2f}x ideal)')

print('\\n=== PERMUTATION (OS8, PLB on) ===')
