// -*- c-basic-offset: 4; indent-tabs-mode: nil -*-
//
// FASTFLOW implementation. See fastflow.h for module-level docs.

#include "fastflow.h"
#include "ecn.h"

#include <algorithm>
#include <cmath>
#include <iostream>

// ===========================================================================
//                        Static parameter defaults
// ===========================================================================
//
// These match the FASTFLOW paper Sec 3.5 reference settings. main_fastflow
// recomputes _bdp_bytes, _base_rtt, _target_rtt, _fi_const, _md_const from
// the actual topology before flows start, so these defaults only matter for
// unit tests that don't initialise the topology first.

uint16_t FastflowSrc::_mtu          = 4000;
double   FastflowSrc::_fd_const     = 0.8;
double   FastflowSrc::_fi_const     = 0.25;
double   FastflowSrc::_md_const     = 2.0;
double   FastflowSrc::_qa_scaling   = 0.8;
double   FastflowSrc::_wtd_alpha    = 0.125;
double   FastflowSrc::_wtd_thresh   = 0.25;
uint32_t FastflowSrc::_k_fastinc    = 2;
simtime_picosec FastflowSrc::_base_rtt   = timeFromUs((uint32_t)12);
simtime_picosec FastflowSrc::_target_rtt = timeFromUs((uint32_t)18);
uint32_t FastflowSrc::_bdp_bytes    = 1500000;
bool     FastflowSrc::_enable_ra_qa   = false;
bool     FastflowSrc::_enable_credits = false;
bool     FastflowSrc::_enable_mcc     = false;
bool     FastflowSrc::_trim_supported = true;

// ===========================================================================
//                        FastflowSrc — constructor
// ===========================================================================
FastflowSrc::FastflowSrc(FastflowRtxTimerScanner& rtx_scanner,
                         TrafficLogger* pktlogger, EventList& eventlist)
    : EventSource(eventlist, "fastflow_src"),
      _flow(pktlogger),
      _pacer(*this, eventlist),
      _traffic_logger(pktlogger)
{
    _established   = false;
    _route         = NULL;
    _sink          = NULL;
    _path_index    = 0;
    _plb           = false;
    _plb_last_good = 0;
    _plb_interval  = timeFromSec(1);

    _highest_sent  = 0;
    _last_acked    = 0;
    _flow_size     = ((uint64_t)1) << 62;
    _packets_sent  = 0;

    // Start at 1 MTU; MI+FI ramps to BDP in ~8 RTTs. Starting at BDP causes
    // a burst storm when many flows fire simultaneously (common in perm/a2a).
    _cwnd          = _mtu;
    _acked         = 0;
    _bytes_ignored = 0;
    _bytes_to_ignore = 0;
    _trigger_qa    = false;
    _avg_wtd       = 0.0;
    _fast_inc_count = 0;
    _in_fast_inc   = false;
    _qa_end        = 0;
    _last_decrease = 0;

    _rtt           = 0;
    _rto           = timeFromUs((uint32_t)200);
    _mdev          = 0;
    // Lower bound on RTO. We use 25us because base RTT at 800Gbps fat-tree
    // is ~12us — a hole stuck because its trim ACK was dropped should be
    // retried after ~2 RTTs, not 100us+.
    _min_rto       = timeFromUs((uint32_t)25);
    _RFC2988_RTO_timeout = 0;
    _rtx_timeout_pending = false;
    _retransmit_cnt = 0;
    _drops         = 0;
    _retransmits_dbg = 0;
    _blocked_rtx_dbg = 0;

    // Initial burst = 1 BDP. The credit check is secondary to cwnd; the burst
    // ensures credits never restrict sending *more* than cwnd in the first
    // BDP worth of bytes. After the burst is consumed, per-packet receiver
    // credits replenish at exactly the delivery rate, so no starvation occurs.
    _initial_burst_remaining = _enable_credits ? _bdp_bytes : ((uint64_t)1 << 62);
    _receiver_credits = 0;
    _msg_start_time = 0;
    _msg_acked      = 0;
    _msg_target_bw  = 0.0;
    _msg_tolerance  = 0.85;

    _start_time     = 0;
    _flow_finished  = false;
    _end_trigger    = NULL;

content.content:
1	// -*- c-basic-offset: 4; indent-tabs-mode: nil -*-
2	//
3	// FASTFLOW: sender-based CC using ECN + RTT + packet trimming.
4	// Implements the algorithm from Bonato et al. 2024 (arXiv 2404.01630),
5	// reproduced and extended for this codebase.
6	//
7	// Layered features (all togglable via static flags so a single source/sink
8	// class covers every variant the paper plan needs):
9	//   - FASTFLOW core: paper Algorithm 1 (FD/MD/FI/MI), Algorithm 2 (QuickAdapt),
10	//                    Algorithm 3 (FastIncrease), Sec 3.5.1 (Wait-to-Decrease).
11	//   - Idea 1: receiver credits + Message-Level CC overrides.
12	//   - Idea 2: coflow-aware asymmetric credit allocation (state on the sink).
13	//   - Idea 3: Receiver-Anchored QuickAdapt — sink stamps its own
14	//             bytes-received-per-trtt onto each ACK, sender uses that
15	//             directly when QuickAdapt fires.
16	
17	#ifndef FASTFLOW_H
18	#define FASTFLOW_H
19	
20	#include <list>
21	#include <map>
22	#include <set>
23	#include <vector>
24	#include <string>
25	
26	#include "config.h"
27	#include "network.h"
28	#include "eventlist.h"
29	#include "loggertypes.h"
30	#include "trigger.h"
31	
32	#include "fastflowpacket.h"
33	#include "coflow_state.h"
34	
35	class FastflowSink;
36	class FastflowSrc;
37	class FastflowRtxTimerScanner;
38	class FastflowPacer;
39	
40	// ===========================================================================
41	// FastflowPacer — runs the source in paced mode when cwnd drops below 1 MTU.
42	// ===========================================================================
43	class FastflowPacer : public EventSource {
44	public:
45	    FastflowPacer(FastflowSrc& src, EventList& eventlist);
46	    bool is_pending() const { return _interpacket_delay > 0; }
47	    void schedule_send(simtime_picosec delay);
48	    void cancel();
49	    void just_sent();
50	    virtual void doNextEvent();
51	
52	private:
53	    FastflowSrc* _src;
54	    simtime_picosec _interpacket_delay;
55	    simtime_picosec _last_send;
56	    simtime_picosec _next_send;
57	};
58	
59	// ===========================================================================
60	// FastflowSrc — the sender.
61	// ===========================================================================
62	class FastflowSrc : public EventSource, public PacketSink, public TriggerTarget {
63	    friend class FastflowSink;
64	    friend class FastflowPacer;
65	    friend class FastflowRtxTimerScanner;
66	
67	public:
68	    FastflowSrc(FastflowRtxTimerScanner& rtx_scanner,
69	                TrafficLogger* pktlogger, EventList& eventlist);
70	
71	    void connect(const Route& routeout, const Route& routeback,
72	                 FastflowSink& sink, simtime_picosec starttime);
73	    virtual void receivePacket(Packet& pkt);
74	    virtual void doNextEvent();
75	    virtual const string& nodename() { return _nodename; }
76	    PacketFlow& flow() { return _flow; }
77	
78	    // Trigger interface
79	    virtual void activate();
80	    void set_end_trigger(Trigger& trigger);
81	
82	    // Workload config
83	    void set_flowsize(uint64_t bytes);
84	    uint64_t flowsize() const { return _flow_size; }
85	    void set_paths(vector<const Route*>* rt);
86	    void enable_plb() { _plb = true; }
87	
88	    // ====================== Global tunables (paper Sec 3.5) ================
89	    static uint16_t _mtu;          // MTU in bytes (data packet payload)
90	    static double   _fd_const;     // Fair decrease constant (0.8)
91	    static double   _fi_const;     // Fair increase constant (0.25 at 100Gbps ref)
92	    static double   _md_const;     // Multiplicative decrease constant (2; 4 if no trim)
93	    static double   _qa_scaling;   // QuickAdapt window scale (0.8)
94	    static double   _wtd_alpha;    // EMA constant for WTD (0.125)
95	    static double   _wtd_thresh;   // WTD trigger threshold (0.25)
96	    static uint32_t _k_fastinc;    // packets per FastIncrease step (2)
97	    static simtime_picosec _base_rtt;     // base RTT for the topology
98	    static simtime_picosec _target_rtt;   // 1.5 * base_rtt (paper default)
99	    static uint32_t _bdp_bytes;    // BDP in bytes for cwnd clamp
100	
101	    // ====================== Feature toggles (CLI-driven) ===================
102	    static bool _enable_ra_qa;     // Idea 3: receiver-anchored QuickAdapt
103	    static bool _enable_credits;   // Idea 1: gate sends on receiver credits
104	    static bool _enable_mcc;       // Idea 1: message-level CC override
105	    static bool _trim_supported;   // if false, double _md and rely on timeouts
106	
107	    // For workload-aware MCC: target bandwidth per flow (bytes/sec)
108	    void set_msg_target_bw(double bytes_per_sec) { _msg_target_bw = bytes_per_sec; }
109	    void set_msg_tolerance(double t)             { _msg_tolerance = t; }
110	    bool message_is_healthy(simtime_picosec now) const;
111	
112	    // Stats
113	    uint64_t packets_sent() const { return _packets_sent; }
114	    uint64_t bytes_acked()  const { return _last_acked; }
115	    uint64_t retransmits()  const { return _retransmits_dbg; }
116	    uint64_t blocked_rtx()  const { return _blocked_rtx_dbg; }
117	
118	    // ====================== Internal accessors for debugging ==============
119	    uint32_t cwnd() const { return _cwnd; }
120	    simtime_picosec rtt() const { return _rtt; }
121	    uint32_t drops() const { return _drops; }
122	
123	protected:
124	    // --- Connectivity ---
125	    bool _established;
126	    const Route* _route;          // outbound route (sender -> sink)
127	    FastflowSink* _sink;
128	    PacketFlow _flow;
129	    vector<const Route*> _paths;  // ECMP path pool
130	    uint32_t _path_index;
131	    bool _plb;                          // PLB enabled
132	    simtime_picosec _plb_last_good;     // timestamp of last congestion-free ACK
133	    simtime_picosec _plb_interval;      // retry-path interval (randomised)
134	
135	    // --- Sending state ---
136	    uint64_t _highest_sent;       // highest seqno ever sent (bytes)
137	    uint64_t _last_acked;         // cumulative ack point
138	    uint64_t _flow_size;          // total bytes to send
139	    uint64_t _packets_sent;       // counter for stats
140	
141	    // --- Core FASTFLOW state (paper Algo 1) ---
142	    uint32_t _cwnd;               // congestion window (bytes)
143	    uint64_t _acked;              // bytes acked in current QuickAdapt window
144	    uint64_t _bytes_ignored;      // accumulator for post-QA grace
145	    uint64_t _bytes_to_ignore;    // ignore-budget after QuickAdapt fires
146	    bool     _trigger_qa;         // a trim/timeout has armed QuickAdapt
147	    double   _avg_wtd;            // EMA of ECN markings for Wait-to-Decrease
148	    uint32_t _fast_inc_count;     // bytes of clean ACKs in current FI window
149	    bool     _in_fast_inc;        // FastIncrease currently active
150	    simtime_picosec _qa_end;      // earliest time a new QuickAdapt may fire
151	    simtime_picosec _last_decrease;
152	
153	    // --- RTT/RTO ---
154	    simtime_picosec _rtt, _rto, _mdev;
155	    simtime_picosec _min_rto;
156	    simtime_picosec _RFC2988_RTO_timeout;
157	    bool _rtx_timeout_pending;
158	    uint32_t _retransmit_cnt;
159	    uint32_t _drops;
160	
161	    // --- Retransmission dedup + deferred retry ---
162	    // Trim ACKs retransmit the trimmed seqno immediately (paper Algo 1).
163	    // _rtx_blockuntil holds (seqno -> earliest-next-retransmit-time) so a
164	    // single dropped packet that gets trimmed several times in quick
165	    // succession only triggers one retransmit per RTT. When a trim arrives
166	    // for a seqno whose block has not expired we stash it in _rtx_pending
167	    // and drain it on the next event whose timestamp clears the block —
168	    // otherwise blocked trims would be silently lost between block-expiry
169	    // and the next RTO fire (which happens at a much coarser cadence).
170	    std::map<FastflowPacket::seq_t, simtime_picosec> _rtx_blockuntil;
171	    std::set<FastflowPacket::seq_t> _rtx_pending;
172	    uint64_t _retransmits_dbg;
173	    uint64_t _blocked_rtx_dbg;
174	
175	    // --- Idea 1: credits + MCC ---
176	    uint64_t _initial_burst_remaining;  // 1 BDP blind send before credits
177	    uint64_t _receiver_credits;         // bytes the sink has authorised
178	    simtime_picosec _msg_start_time;
179	    uint64_t _msg_acked;                // bytes acked since msg start
180	    double   _msg_target_bw;            // bytes/sec the message expects
181	    double   _msg_tolerance;            // healthy if acked >= elapsed*bw*tol
182	
183	    // --- FCT bookkeeping ---
184	    simtime_picosec _start_time;
185	    bool _flow_finished;
186	    Trigger* _end_trigger;
187	
188	    // Pacer (used when cwnd < 1 MTU)
189	    FastflowPacer _pacer;
190	    simtime_picosec _pacing_delay;
191	
192	    // Logging
193	    TrafficLogger* _traffic_logger;
194	    string _nodename;
195	    FastflowRtxTimerScanner* _rtx_scanner;
196	
197	private:
198	    // --- Control loop (Algorithm 1) ---
199	    void handle_ack(FastflowAck& ack);
200	    bool wait_to_decrease(bool ecn, simtime_picosec now);
201	    bool quick_adapt(FastflowAck& ack, simtime_picosec now);
202	    bool fast_increase(FastflowAck& ack);
203	    void fair_decrease(uint16_t pkt_size);
204	    void multiplicative_decrease(uint16_t pkt_size, simtime_picosec rtt_sample);
205	    void fair_increase(uint16_t pkt_size);
206	    void multiplicative_increase(uint16_t pkt_size, simtime_picosec rtt_sample);
207	    void clamp_cwnd();
208	    void update_rtt(simtime_picosec sample);
209	
210	    // --- Sending ---
211	    int  send_packets();
212	    bool send_next_packet();
213	    void retransmit_packet();
214	    void send_syn();
215	    bool can_send_one_mtu() const;     // checks credits + cwnd
216	
217	    // --- Trim / timeout reaction (Algo 1 lines 28-34) ---
218	    void handle_trim(FastflowAck& ack);
219	    void retransmit_seqno(FastflowPacket::seq_t seqno);
220	    void drain_pending_rtx();
221	    void prune_blockuntil();
222	    bool can_retransmit(FastflowPacket::seq_t seqno) const;
223	    void rtx_timer_hook(simtime_picosec now, simtime_picosec period);
224	
225	    // --- Completion ---
226	    void maybe_report_completion();
227	
228	    void startflow();
229	};
230	
231	// ===========================================================================
232	// FastflowSink — the receiver.
233	// ===========================================================================
234	class FastflowSink : public PacketSink, public Logged {
235	    friend class FastflowSrc;
236	
237	public:
238	    FastflowSink();
239	    virtual void receivePacket(Packet& pkt);
240	    virtual const string& nodename() { return _nodename; }
241	    void connect(FastflowSrc& src, const Route& routeback);
242	    virtual void setName(const string& name) { Logged::setName(name); _nodename = name; }
243	
244	    // Idea 2: register this sink as part of a coflow.
245	    void set_coflow(CoflowId cid, SenderId sid);
246	
247	    // Idea 1: credit-grant emission (called periodically when credits enabled).
248	    void enable_credit_mode(linkspeed_bps host_linkspeed);
249	    void issue_credit_if_due(simtime_picosec now);
250	
251	    uint64_t cumulative_ack() const { return _cumulative_ack; }
252	    uint32_t drops()          const { return _drops; }
253	
254	protected:
255	    FastflowSrc* _src;
256	    const Route* _route_back;
257	    string _nodename;
258	
259	    // ACK state
260	    uint64_t _cumulative_ack;          // last contiguous byte
261	    std::list<FastflowPacket::seq_t> _received;  // out-of-order holes
262	    uint32_t _drops;
263	
264	    // RA-QA window
265	    uint64_t _bytes_received_window;       // current (possibly partial) window
266	    uint64_t _bytes_received_last_window;  // previous completed window (stable)
267	    simtime_picosec _window_start;
268	
269	    // Credit mode (Idea 1)
270	    bool _credit_mode;
271	    linkspeed_bps _host_linkspeed;
272	    simtime_picosec _next_credit_time;
273	    uint32_t _credit_quantum;          // default ~1 MTU per RTT/N
274	
275	    // Coflow membership (Idea 2)
276	    CoflowId _coflow_id;
277	    SenderId _sender_id;
278	    uint64_t _bytes_received_total;    // for coflow progress tracking
279	
280	private:
281	    void send_ack(FastflowPacket& pkt, bool trimmed, simtime_picosec now);
282	    void update_recv_window(uint32_t pkt_size, simtime_picosec now);
283	};
284	
285	// ===========================================================================
286	// FastflowRtxTimerScanner — periodic scan to fire RTOs.
287	// ===========================================================================
288	class FastflowRtxTimerScanner : public EventSource {
