        // duplicate / out of order before cum_ack — ignore
    } else {
        if (_received.empty() || seqno > _received.back()) {
            _received.push_back(seqno);
        } else {
            for (auto it = _received.begin(); it != _received.end(); ++it) {
                if (seqno == *it) break;
                if (seqno < *it) { _received.insert(it, seqno); break; }
            }
        }
    }

