                           (uint32_t)(_flow_size + 1 - seqno));
    FastflowPacket* p = FastflowPacket::newpkt(_flow, *_route, seqno, sz);
    p->set_ts(eventlist().now());
    p->flow().logTraffic(*p, *this, TrafficLogger::PKT_CREATESEND);
    p->sendOn();
    _packets_sent += 1;
